\begin{outcome}
\begin{enumerate}
\item[A.] Gunakan operasi elementer untuk menemukan solusi suatu sistem persamaan linear.

\begin{definition}{Sistem Persamaan Linear}\label{def:systemoflinearequations}
Suatu \textbf{sistem persamaan linear} \index{sistem persamaan} adalah daftar persamaan,
\begin{equation*}
\begin{array}{c}
a_{11}x_{1}+a_{12}x_{2}+\cdots +a_{1n}x_{n}=b_{1} \\
a_{21}x_{1}+a_{22}x_{2}+\cdots +a_{2n}x_{n}=b_{2} \\
\vdots \\
a_{m1}x_{1}+a_{m2}x_{2}+\cdots +a_{mn}x_{n}=b_{m}
\end{array}
\end{equation*}
dengan $a_{ij}$ dan $b_{j}$ berupa bilangan real. Bentuk di atas merupakan sistem
yang terdiri atas $m$ persamaan dalam $n$ variabel, $x_{1},x_{2}\cdots ,x_{n}$.
 Secara lebih ringkas, dengan menggunakan
notasi penjumlahan, bentuk di atas dapat ditulis sebagai
\begin{equation*}
\sum_{j=1}^{n}a_{ij}x_{j}=b_{i},
\text{ }i=1,2,3,\cdots ,m
\end{equation*}
Terakhir, kita dapat menuliskannya dalam notasi matriks sebagai
$$
A \x = \b 
$$
dengan
$$
A = \begin{bmatrix}
a_{11} & a_{12} & \dots & a_{1n}\\
a_{21} & a_{22} & \dots & a_{2n}\\
\vdots\\
a_{m1} & a_{m2} & \dots & a_{mn}
\end{bmatrix}, \ \ \ \x = \begin{bmatrix} x_1 \\ x_2 \\ \vdots \\ x_n\end{bmatrix}, \ \ \text{ dan } \ \ \b = \begin{bmatrix} b_1 \\ b_2 \\ \vdots \\ b_m\end{bmatrix}.
$$
\end{definition}

\begin{definition}{Sistem Persamaan Homogen}\label{def:homogeneoussystem}
Suatu sistem persamaan disebut \textbf{homogen} \index{sistem persamaan!homogen} jika setiap persamaan dalam
sistem tersebut sama dengan $0$. Sistem homogen memiliki bentuk
\begin{equation*}
\begin{array}{c}
a_{11}x_{1}+a_{12}x_{2}+\cdots +a_{1n}x_{n}= 0 \\
a_{21}x_{1}+a_{22}x_{2}+\cdots +a_{2n}x_{n}= 0  \\
\vdots \\
a_{m1}x_{1}+a_{m2}x_{2}+\cdots +a_{mn}x_{n}= 0 
\end{array}
\end{equation*}
dengan $a_{ij}$ berupa skalar dan $x_{i}$ berupa variabel.
\end{definition}

\begin{definition}{Sistem Konsisten dan Tak Konsisten}\label{def:consistentandinconsistent}
Suatu sistem persamaan linear disebut
\index{sistem konsisten} \textbf{konsisten} jika terdapat sedikitnya satu solusi. Sistem tersebut
disebut
\index{sistem tak konsisten} \textbf{tak konsisten} jika tidak memiliki solusi.
\end{definition}

% Istilah bentuk eselon untuk lampiran Bahasa Indonesia. Definisi pada
% preambul gabungan masih memakai teks bahasa Inggris.
\renewcommand{\RREF}{Bentuk Eselon Baris Tereduksi}
\renewcommand{\rref}{bentuk eselon baris tereduksi}
\renewcommand{\EF}{Bentuk Eselon Baris}
\renewcommand{\ef}{bentuk eselon baris}

Sebagai contoh, perhatikan sistem linear pada Contoh \ref{exa:solvingasystemwithelementaryops}
\begin{equation*}
\begin{array}{ccccccc}
x&+&3y&+&6z&=&25 \\
2x&+&7y&+&14z&=&58 \\
&&2y&+&5z&=&19
\end{array}
\end{equation*}
Sistem ini dapat ditulis sebagai matriks diperbesar, sebagai berikut \:
\begin{equation*}
\leftB 
\begin{array}{rrr|r}
1 & 3 & 6 & 25 \\
2 & 7 & 14 & 58 \\
0 & 2 & 5 & 19
\end{array}
\rightB 
\end{equation*}

Baris-baris matriks diperbesar bersesuaian dengan persamaan-persamaan dalam sistem. Sebagai contoh, baris
teratas dalam matriks diperbesar,
$\leftB
\begin{array}{rrrrr}
1 & 3 & 6 & | & 25
\end{array}
\rightB$
 bersesuaian dengan persamaan
\begin{equation*}
x+3y+6z=25.
\end{equation*}

\begin{definition}{Matriks Diperbesar Suatu Sistem Linear}\label{def:augmentedmatrix}
Untuk sistem linear berbentuk
\begin{equation*}
\begin{array}{c}
a_{11}x_{1}+\cdots +a_{1n}x_{n}=b_{1} \\
\vdots \\
a_{m1}x_{1}+\cdots +a_{mn}x_{n}=b_{m}
\end{array}
\end{equation*}
dengan $x_{i}$ berupa variabel serta $a_{ij}$ dan $b_{i}$ berupa konstanta,
matriks diperbesar \index{matriks!matriks diperbesar} dari sistem ini diberikan oleh
\begin{equation*}
\leftB
\begin{array}{rrr|r}
a_{11} & \cdots & a_{1n} &  b_{1} \\
\vdots &  & \vdots &  \vdots \\
a_{m1} & \cdots & a_{mn} &  b_{m}
\end{array}
\rightB 
\end{equation*}
\end{definition}

\item Ganti suatu baris dengan baris tersebut ditambah sembarang kelipatan dari baris lain.
\end{enumerate}
\end{definition}

Ingat kembali cara kita menyelesaikan Contoh \ref{exa:solvingasystemwithelementaryops}.
Kita dapat melakukan langkah-langkah yang persis sama seperti di atas, tetapi sekarang dalam konteks matriks diperbesar dan dengan menggunakan operasi baris.
Matriks diperbesar sistem ini adalah
\begin{equation*}
\leftB 
\begin{array}{rrr|r}
1 & 3 & 6 &  25 \\
2 & 7 & 14 &  58 \\
0 & 2 & 5 &  19
\end{array}
\rightB 
\end{equation*}
Jadi, langkah pertama dalam
menyelesaikan sistem yang diberikan oleh \ref{solvingasystem1} adalah mengambil $\left( -2\right) $ kali baris pertama
matriks diperbesar dan menambahkannya ke baris kedua,
\begin{equation*}
\leftB
\begin{array}{rrr|r}
1 & 3 & 6 & 25 \\
0 & 1 & 2 & 8 \\
0 & 2 & 5 & 19
\end{array}
\rightB 
\end{equation*}
Perhatikan bahwa hal ini bersesuaian dengan \ref{solvingasystem2}. Selanjutnya, ambil $\left( -2\right) $
kali baris kedua dan tambahkan ke baris ketiga,
\begin{equation*}
\leftB 
\begin{array}{rrr|r}
1 & 3 & 6 & 25 \\
0 & 1 & 2 & 8 \\
0 & 0 & 1 & 3
\end{array}
\rightB
\end{equation*}
Matriks diperbesar ini bersesuaian dengan sistem
\begin{equation*}
\begin{array}{ccccccc}
x&+&3y&+&6z&=&25 \\
&&y&+&2z&=&8 \\
&&&&z&=&3
\end{array}
\end{equation*}
yang sama dengan \ref{solvingasystem3}. Dengan substitusi balik, Anda memperoleh solusi
$x=1,y=2,$ dan $z=3.$

\begin{definition}{\EF}\label{def:echelonform}
Suatu matriks diperbesar berada
\index{\ef} dalam \textbf{\ef} jika

\begin{definition}{\RREF}\label{def:rref}
Suatu matriks
\index{\rref} diperbesar berada dalam \textbf{\rref } jika

Jadi, setiap matriks \rref \;juga berada dalam \ef. Kebalikannya belum tentu benar;
 kita tidak dapat menganggap bahwa setiap matriks dalam \ef \;juga berada dalam \rref. Namun, sering kali
\ef \;sudah cukup untuk memberikan informasi mengenai solusi suatu sistem.

\begin{equation*}
\leftB
\begin{array}{rrr|r}
0 & 0 & 0 & 0 \\
1 & 2 & 3 & 3 \\
0 & 1 & 0 & 2 \\
0 & 0 & 0 & 1 \\
0 & 0 & 0 & 0
\end{array}
\rightB ,\leftB
\begin{array}{rr|r}
