\begin{definition}{Solusi Trivial}\label{def:trivialsolution}
Perhatikan sistem persamaan homogen yang diberikan oleh
\begin{equation*}
\begin{array}{c}
a_{11}x_{1}+a_{12}x_{2}+\cdots +a_{1n}x_{n}= 0 \\
a_{21}x_{1}+a_{22}x_{2}+\cdots +a_{2n}x_{n}= 0  \\
\vdots \\
a_{m1}x_{1}+a_{m2}x_{2}+\cdots +a_{mn}x_{n}= 0 
\end{array}
\end{equation*}
Maka $x_{1} = 0, x_{2} = 0, \cdots, x_{n} =0$ selalu merupakan
solusi sistem ini. Kita menyebutnya \textbf{solusi trivial} \index{solusi trivial}.
\end{definition}

\begin{example}{Solusi Sistem Persamaan Homogen}\label{exa:homogeneoussolution}
Temukan solusi nontrivial sistem persamaan homogen berikut
\begin{equation*}
\begin{array}{cccccccc}
2x &+& y &-& z &=& 0 \\
x &+& 2y &-& 2z &=& 0
\end{array}
\end{equation*}
\end{example}

\begin{solution}
Perhatikan bahwa sistem ini memiliki $m = 2$ persamaan dan $n = 3$ variabel, sehingga $n>m$.
Oleh karena itu, berdasarkan pembahasan sebelumnya, kita memperkirakan bahwa sistem ini memiliki tak berhingga banyak solusi.

Proses yang kita gunakan untuk menemukan solusi sistem persamaan homogen
sama dengan proses yang digunakan pada bagian sebelumnya.
Pertama, kita menyusun matriks diperbesar, yaitu
\begin{equation*}
\leftB
\begin{array}{rrr|r}
2 & 1 & -1 & 0 \\ 
1 & 2 & -2 & 0
\end{array}
\rightB
\end{equation*}
Kemudian, kita membawa matriks ini ke \rref-nya, yang diberikan di bawah.
\begin{equation*}
\leftB
\begin{array}{rrr|r}
1 & 0 & 0 & 0 \\ 
0 & 1 & -1 & 0
\end{array}
\rightB
\end{equation*}
Sistem persamaan yang bersesuaian adalah
\begin{equation*}
\begin{array}{c}
x = 0 \\
y - z =0 \\
\end{array}
\end{equation*}
Karena $z$ tidak dibatasi oleh persamaan mana pun, kita mengetahui bahwa variabel ini akan menjadi parameter.
Misalkan $z=t$, dengan $t$ berupa sembarang bilangan.
Oleh karena itu, solusi kita berbentuk
\begin{equation*}
\begin{array}{c}
x = 0 \\
y = z = t \\
z = t
\end{array}
\end{equation*}
Jadi, sistem ini memiliki tak berhingga banyak solusi dengan satu parameter $t$.
\end{solution}

Kolom ini memiliki nama khusus, yaitu \textbf{solusi dasar}\index{solusi dasar}. Solusi dasar suatu sistem
adalah kolom yang disusun dari koefisien parameter dalam solusi. Kita sering menyatakan solusi dasar
dengan $X_1, X_2$, dan seterusnya, bergantung pada banyaknya solusi yang muncul. Oleh karena itu, Contoh \ref{exa:homogeneoussolution}
memiliki solusi dasar $X_1 = \leftB
\begin{array}{r}
0\\
1\\
1
\end{array}
\rightB$.

\begin{example}{Solusi Dasar Sistem Homogen}\label{exa:basicsolutions}
Perhatikan sistem persamaan homogen berikut.
\begin{equation*}
\begin{array}{cccccccc}
x &+& 4y &+& 3z &=& 0 \\
3x &+& 12y &+& 9z &=& 0
\end{array}
\end{equation*}
Temukan solusi dasar sistem ini.
\end{example}

\begin{solution}
Matriks diperbesar sistem ini dan \rref \;yang dihasilkan adalah
\begin{equation*}
\leftB
\begin{array}{rrr|r}
1 & 4 & 3 & 0 \\
3 & 12 & 9 & 0
\end{array}
\rightB
\rightarrow \cdots \rightarrow
\leftB
\begin{array}{rrr|r}
1 & 4 & 3 & 0 \\
0 & 0 & 0 & 0
\end{array}
\rightB
\end{equation*}
Jika ditulis sebagai persamaan, sistem ini diberikan oleh
\begin{equation*}
x + 4y +3z=0
\end{equation*}
Perhatikan bahwa hanya $x$ yang bersesuaian dengan kolom pivot. Dalam hal ini, kita akan memiliki dua parameter,
satu untuk $y$ dan satu untuk $z$. Misalkan $y = s$ dan $z=t$ untuk sembarang bilangan $s$ dan $t$. Maka solusi kita menjadi
\begin{equation*}
\begin{array}{c}
x = -4s - 3t \\
y = s \\
z = t
\end{array}
\end{equation*}
yang dapat ditulis sebagai
\begin{equation*}
\leftB
\begin{array}{r}
x\\
y\\
z
\end{array}
\rightB
=
\leftB
\begin{array}{r}
0\\
0\\
0
\end{array}
\rightB
+
s
\leftB
\begin{array}{r}
-4 \\
1 \\
0
\end{array}
\rightB
+ 
t
\leftB
\begin{array}{r}
-3 \\
0 \\
1
\end{array}
\rightB
\end{equation*}
Di sini Anda dapat melihat bahwa kita memiliki dua kolom koefisien yang bersesuaian dengan parameter, yaitu satu untuk $s$ dan satu untuk $t$.
Oleh karena itu, sistem ini memiliki dua solusi dasar, yaitu
\begin{equation*}
X_1=
\leftB
\begin{array}{r}
-4 \\
1 \\
0
\end{array}
\rightB, X_2 = \leftB
\begin{array}{r}
-3 \\
0 \\
1
\end{array}
\rightB
\end{equation*} 
\end{solution}

\begin{definition}{Kombinasi Linear}\label{def:linearcombination-columns}
Misalkan $X_1,\cdots ,X_n,V$ merupakan matriks kolom. Maka
$V$ disebut \textbf{kombinasi linear}
\index{kombinasi linear}dari kolom-kolom $X_1,\cdots , X_n $
jika terdapat skalar $a_{1},\cdots ,a_{n}$ sedemikian
sehingga
\begin{equation*}
V = a_1 X_1 + \cdots + a_n X_n
\end{equation*}
\end{definition}

\begin{definition}{Rank Suatu Matriks}\label{def:rank}
Misalkan $A$ merupakan suatu matriks dan perhatikan sembarang \ef \;dari $A$.
Maka banyaknya $r$ entri utama $A$ tidak bergantung pada \ef \;yang Anda pilih dan disebut \textbf{rank} \index{matriks!rank} dari $A$. Kita menyatakannya dengan $\func{rank}(A)$.
\end{definition}

\begin{example}{Menentukan Rank Suatu Matriks}\label{exa:rankofamatrix}
Perhatikan matriks
\begin{equation*}
\leftB
\begin{array}{rrr}
1 & 2 & 3 \\
1 & 5 & 9 \\
2 & 4 & 6 
\end{array}
\rightB
\end{equation*}
Berapakah rank-nya?
\end{example}

\begin{solution}
Pertama, kita perlu menemukan \rref \;dari $A$. Dengan algoritme yang biasa, kita memperoleh
\begin{equation*}
\leftB
\begin{array}{rrr}
\fbox{1} & 0 & -1 \\
0 & \fbox{1} & 2 \\
0 & 0 & 0
\end{array}
\rightB
\end{equation*}
Di sini kita memiliki dua entri utama, atau dua posisi pivot, yang diperlihatkan dalam kotak di atas. Rank $A$ adalah $r = 2.$
\end{solution}

\begin{theorem}{Rank dan Solusi Sistem Homogen}\label{thm:rankhomogeneoussolutions}
Misalkan $A$ merupakan matriks koefisien $m \times n$ yang bersesuaian dengan suatu sistem persamaan homogen, dan misalkan $A$ memiliki rank $r$.
Maka solusi sistem yang bersesuaian memiliki $n-r$ parameter.
\end{theorem}

\begin{theorem}{Rank dan Solusi Sistem Persamaan Konsisten}\label{thm:rankconsistentsolutions}
Misalkan $A$ merupakan matriks diperbesar $m \times \left( n+1 \right) $ yang bersesuaian dengan suatu sistem persamaan konsisten dalam $n$ variabel, dan misalkan $A$ memiliki rank $r$.
Maka
\begin{enumerate}
\item sistem memiliki solusi unik jika $r = n $
\item sistem memiliki tak berhingga banyak solusi jika $r < n$
\end{enumerate}
\end{theorem}

\begin{enumerate}
\item {\em Tidak Ada Solusi \em}
Teorema di atas mengasumsikan bahwa sistem tersebut konsisten, yaitu bahwa sistem memiliki solusi. Ternyata matriks
diperbesar dari suatu sistem tanpa solusi dapat memiliki sembarang rank $r$ asalkan $r>1$. Oleh karena itu, kita harus mengetahui
bahwa sistem tersebut konsisten agar dapat menggunakan teorema ini.

\item {\em Tak Berhingga Banyak Solusi \em}
Misalkan $r<n$. Maka terdapat tak berhingga banyak solusi. Banyaknya posisi pivot (dan karena itu banyaknya entri utama) lebih kecil daripada banyaknya kolom, yang berarti bahwa tidak setiap kolom merupakan kolom pivot. Kolom-kolom yang tidak merupakan kolom pivot bersesuaian dengan parameter. Bahkan,
dalam hal ini kita memiliki $n-r$ parameter.
\end{enumerate}

\begin{example}{Memverifikasi bahwa Pasangan Terurut Merupakan Solusi}\label{exa:verifyingorderedpairsolution}
Verifikasikan secara aljabar bahwa $\left(x, y \right) = \left( -1, 4 \right)$ merupakan solusi sistem persamaan berikut.
\[
\begin{array}{c}
x+y=3 \\
y-x=5  
\label{eq1.2.1}
\end{array}
\]
\end{example}

\begin{definition}{Operasi Elementer}\label{def:elementaryoperations}
\textbf{Operasi elementer} \index{operasi elementer} adalah
operasi-operasi berikut.

\begin{example}{Dampak Operasi Elementer}\label{exa:effectsofelementaryoperation}
\label{example:effectsofelementaryoperation}
Tunjukkan bahwa sistem
\begin{equation*}
\begin{array}{cccccc}
x&+&y&=&7 \\
2x&-&y&=&8
\end{array}
\end{equation*}
memiliki solusi yang sama dengan sistem
\begin{equation*}
\begin{array}{cccccc}
x&+&y&=&7 \\
&&-3y&=&-6
\end{array}
\end{equation*}
\end{example}

\begin{solution}
Perhatikan bahwa sistem kedua diperoleh dengan mengambil persamaan kedua dari sistem pertama
dan menambahkan -2 kali persamaan pertama, sebagai berikut:
\begin{equation*}
2x-y + (-2)(x+y) = 8 + (-2)(7)
\end{equation*}
Dengan menyederhanakannya, kita memperoleh
\begin{equation*}
-3y=-6
\end{equation*}
yang merupakan persamaan kedua dalam sistem kedua.
Sekarang, dari sini kita dapat mencari $y$ dan melihat bahwa $y=2$. Selanjutnya, kita menyubstitusikan nilai ini ke dalam persamaan pertama sebagai berikut \:
\begin{equation*}
x+y=x+2=7
\end{equation*}
Jadi $x=5$, sehingga $\left( x,y\right) = \left(5,2 \right)$ merupakan solusi sistem kedua.
Kita ingin memeriksa apakah $\left(5,2 \right)$ juga merupakan solusi sistem pertama. Kita memeriksanya dengan menyubstitusikan $\left(x, y \right) = \left(5,2 \right)$
ke dalam sistem dan memastikan bahwa persamaan-persamaannya benar.
\begin{equation*}
\begin{array}{c}
x+y = \left(5 \right)+ \left( 2 \right) = 7 \\
2x-y= 2 \left(5 \right) - \left( 2 \right) = 8
\end{array}
\end{equation*}
Jadi, $\left(5,2 \right)$ juga merupakan solusi sistem pertama.
\end{solution}

\begin{theorem}{Operasi Elementer dan Solusi}\label{thm:elementaryoperationsandsolns}
Misalkan Anda memiliki sistem dua persamaan linear
\begin{equation}
 \begin{array}{c}
  E_{1}=b_{1}\\
  E_{2}=b_{2}
\end{array} \label{system}
\end{equation}
Maka sistem-sistem berikut memiliki himpunan solusi yang sama dengan \ref{system}:
\begin{enumerate}
\item   \begin{equation}
	\begin{array}{c}
	E_{2}=b_{2}\\
	E_{1}=b_{1}
	\end{array}
	\label{thm1.9.1}
	\end{equation}
\item  \begin{equation}
	\begin{array}{c}
	E_{1}=b_{1} \\
	kE_{2}=kb_{2}\\        
	\end{array}
	\label{thm1.9.2}
	\end{equation}
  untuk sembarang skalar $k$, asalkan $k\neq0$.
\item \begin{equation}
      \begin{array}{c}
       E_{1}=b_{1} \\
       E_{2}+kE_{1}=b_{2}+kb_{1}
       \end{array}  
	\label{thm1.9.3}
	\end{equation}
	untuk sembarang skalar $k$ (termasuk $k=0$).

Sebelum melanjutkan ke pembuktian Teorema \ref{thm:elementaryoperationsandsolns},
marilah kita membahas teorema ini dalam konteks Contoh \ref{exa:effectsofelementaryoperation}. Dalam hal ini,
\begin{equation*}
\begin{array}{cc}
E_{1} = x+y, & b_{1} = 7 \\
E_{2} = 2x-y, & b_{2} = 8 
\end{array}
\end{equation*}
Ingat kembali operasi elementer yang kita gunakan untuk mengubah sistem dalam solusi contoh tersebut.
Pertama, kita menambahkan $\left( -2 \right)$ kali persamaan pertama ke persamaan kedua.
Menurut Teorema \ref{thm:elementaryoperationsandsolns}, tindakan ini dinyatakan sebagai
\begin{equation*}
E_{2} + \left( -2 \right) E_{1} = b_{2} + \left( -2 \right)b_{1}
\end{equation*}
atau
\begin{equation*}
2x-y + \left( -2 \right) \left(x+y \right) = 8 + \left( -2 \right) 7
\end{equation*}
Hal ini menghasilkan sistem kedua dalam Contoh \ref{example:effectsofelementaryoperation}, yaitu
\begin{equation*}
\begin{array}{c}
E_{1} = b_{1} \\
E_{2} + \left( -2 \right) E_{1} = b_{2} + \left( -2 \right) b_{1}
\end{array}
\end{equation*}

\begin{equation}
\begin{array}{ccccccc}
x&+&3y&+&6z&=&25 \\
2x&+&7y&+&14z&=&58 \\
&&2y&+&5z&=&19
\end{array}
\label{solvingasystem1}
\end{equation}
\end{example}

\begin{solution}
Kita dapat menghubungkan sistem ini dengan Teorema \ref{thm:elementaryoperationsandsolns} di atas. Dalam hal ini, kita memiliki
\begin{equation*}
\begin{array}{c c}
E_{1} = x + 3y + 6z, & b_{1} = 25\\
E_{2} = 2x+7y+14z, & b_{2} = 58 \\
E_{3} = 2y+5z, & b_{3} = 19 
\end{array}
\end{equation*}
Teorema \ref{thm:elementaryoperationsandsolns} menyatakan bahwa jika kita melakukan operasi elementer pada sistem ini,
kita tidak akan mengubah himpunan solusinya. Oleh karena itu,
kita dapat menyelesaikan sistem ini menggunakan operasi elementer yang diberikan dalam Definisi \ref{def:elementaryoperations}.
Pertama, ganti persamaan kedua dengan hasil penambahan $\left( -2\right)$
kali persamaan pertama ke persamaan kedua. Hal ini menghasilkan sistem
\begin{equation}
\begin{array}{c}
x+3y+6z=25 \\
y+2z=8 \\
2y+5z=19
\end{array}
\label{solvingasystem2}
\end{equation}
Sekarang, ganti persamaan ketiga dengan hasil penambahan $\left( -2\right) $ kali
persamaan kedua ke persamaan ketiga. Hal ini menghasilkan sistem
\begin{equation}
\begin{array}{c}
x+3y+6z=25 \\
y+2z=8 \\
z=3
\end{array}
\label{solvingasystem3}
\end{equation}
Pada tahap ini, kita dapat menemukan solusinya dengan mudah. Ambil $z=3$ dan substitusikan kembali nilai ini ke dalam
 persamaan sebelumnya untuk mencari $y$, lalu lakukan hal serupa untuk mencari $x$.
\begin{equation*}
\begin{array}{c}
x + 3y + 6 \left(3 \right) = x + 3y + 18 = 25\\
y + 2 \left(3 \right) = y + 6 = 8 \\
z = 3
\end{array}
\end{equation*}
Persamaan kedua kini menjadi
\begin{equation*}
y+6=8
\end{equation*}
Dari persamaan ini Anda dapat melihat bahwa $y = 2$. Oleh karena itu, kita dapat menyubstitusikan nilai tersebut ke dalam persamaan pertama sebagai berikut:
\begin{equation*}
x + 3 \left(2 \right) + 18 = 25
\end{equation*}
Dengan menyederhanakan persamaan ini, kita menemukan bahwa $x=1$.
Jadi, solusi sistem ini adalah $\left( x,y,z \right) = \left( 1,2,3 \right)$.
Proses ini disebut \textbf{substitusi balik}. \index{substitusi balik}

Sebagai alternatif, pada \ref{solvingasystem3} Anda dapat melanjutkan sebagai berikut. Tambahkan $\left(
-2\right) $ kali persamaan ketiga ke persamaan kedua, lalu tambahkan $\left(
-6\right) $ kali persamaan kedua ke persamaan pertama. Hal ini menghasilkan
\begin{equation*}
\allowbreak
\begin{array}{c}
x+3y=7 \\
y=2 \\
z=3
\end{array}
\end{equation*}
Sekarang tambahkan $\left( -3\right) $ kali persamaan kedua ke persamaan pertama. Hal ini menghasilkan
\begin{equation*}
\allowbreak
\begin{array}{c}
x=1 \\
y=2 \\
z=3
\end{array}
\end{equation*}
suatu sistem yang memiliki himpunan solusi yang sama dengan sistem semula. Cara ini
menghindari substitusi balik dan menghasilkan himpunan solusi yang sama. Anda dapat memilih metode yang lebih disukai karena keduanya menghasilkan solusi yang benar,
$\left( x,y,z \right) = \left(1,2,3\right)$.
\end{solution}

\begin{example}{Variabel Dasar dan Variabel Bebas}\label{exa:basicfree}
Temukan variabel dasar dan variabel bebas dalam sistem
\[
\begin{array}{c}
x+2y-z+w=3 \\
x+y-z+w=1 \\
x+3y-z+w=5
\end{array}
\]
\end{example}

\begin{proposition}{Variabel Dasar dan Variabel Bebas}\label{prop:basicfree}
Jika $x_i$ merupakan variabel dasar suatu sistem persamaan linear homogen, maka setiap solusi sistem dengan $x_j=0$ untuk semua variabel bebas $x_j$ dengan $j>i$ juga harus memiliki $x_i=0$.
\end{proposition}

\begin{lemma}{Solusi dan \RREF \;Suatu Matriks}\label{lem:rrefsolutions}
Misalkan $A$ dan $B$ merupakan dua matriks diperbesar yang berbeda bagi dua sistem homogen yang terdiri atas $m$ persamaan dalam $n$ variabel, sedemikian sehingga $A$ dan $B$ masing-masing berada dalam \rref. Maka kedua sistem tersebut tidak memiliki solusi yang persis sama.
\end{lemma}
\ifdefined\showproofs
\begin{proof}
Sehubungan dengan sistem linear yang bersesuaian dengan matriks $A$ dan $B$, terdapat dua kasus yang perlu dibahas:
\begin{itemize}
\item Kasus $1$: kedua sistem memiliki variabel dasar yang sama
\item Kasus $2$: kedua sistem tidak memiliki variabel dasar yang sama
\end{itemize}
Dalam kasus $1$, kedua matriks memiliki posisi pivot yang persis sama. Namun, karena $A$ dan $B$ tidak identik, terdapat suatu baris $A$ yang berbeda dari baris $B$ yang bersesuaian, meskipun masing-masing baris memiliki pivot pada posisi kolom yang sama. Misalkan $i$ adalah indeks posisi kolom tersebut. Karena kedua matriks berada dalam \rref, kedua baris harus berbeda pada suatu entri dalam kolom $j>i$. Misalkan entri-entri tersebut adalah $a$ dalam $A$ dan $b$ dalam $B$, dengan $a \neq b$. Karena $A$ berada dalam \rref, jika $x_j$ merupakan variabel dasar bagi sistem linearnya, kita akan memiliki $a=0$. Demikian pula, jika $x_j$ merupakan variabel dasar bagi sistem linear matriks $B$, kita akan memiliki $b=0$. Karena $a$ dan $b$ tidak sama, keduanya tidak mungkin sama-sama bernilai $0$, sehingga $x_j$ tidak mungkin merupakan variabel dasar bagi kedua sistem linear. Namun, karena kedua sistem memiliki variabel dasar yang sama, $x_j$ harus merupakan variabel bebas bagi masing-masing sistem. Sekarang kita memperhatikan solusi sistem ketika $x_j$ ditetapkan sama dengan $1$ dan semua variabel bebas lainnya ditetapkan sama dengan $0$. Untuk pilihan parameter ini, solusi sistem bagi matriks $A$ memiliki $x_j=-a$, sedangkan solusi sistem bagi matriks $B$ memiliki $x_j=-b$, sehingga kedua sistem memiliki solusi yang berbeda.

\begin{theorem}{Matriks Ekuivalen}\label{thm:equivalent}
Kedua sistem persamaan linear yang bersesuaian dengan dua matriks diperbesar yang ekuivalen memiliki solusi yang persis sama.
\end{theorem}

\begin{theorem}{Keunikan \RREF}\label{thm:uniquerref}
Setiap matriks $A$ ekuivalen dengan tepat satu matriks dalam \rref.
\end{theorem}

\ifdefined\showproofs
\begin{proof}
Misalkan $A$ merupakan matriks $m \times n$, dan misalkan $B$ dan $C$ merupakan matriks dalam \rref{} yang masing-masing ekuivalen dengan $A$. Cukup ditunjukkan bahwa $B=C$.

Saat menjumlahkan matriks, semua matriks dalam penjumlahan harus berukuran sama.
Sebagai contoh,
\begin{equation*}
\leftB
\begin{array}{rr}
1 & 2 \\
3 & 4 \\
5 & 2
\end{array}
\rightB 
\end{equation*}
dan
\begin{equation*}
\leftB
\begin{array}{rrr}
-1 & 4 & 8\\
2 & 8 & 5
\end{array}
\rightB 
\end{equation*}
tidak dapat dijumlahkan karena yang satu berukuran $3 \times 2$, sedangkan yang lain berukuran $2 \times 3$.

Namun, penjumlahan
\begin{equation*}
\leftB
\begin{array}{rrr}
4 & 6 & 3\\
5 & 0 & 4\\
11 & -2 & 3
\end{array}
\rightB 
+
\leftB
\begin{array}{rrr}
0 & 5 & 0 \\
4 & -4 & 14 \\
1 & 2 & 6
\end{array}
\rightB
\end{equation*}
dapat dilakukan.

\begin{definition}{Penjumlahan Matriks}\label{def:additionofmatrices}
Misalkan $A=\leftB a_{ij}\rightB $ dan $B=\leftB b_{ij}\rightB $ adalah dua
matriks $m\times n$. Maka $A+B=C$ \index{matriks!penjumlahan}, dengan $C$ sebagai matriks $m \times n$
$C=\leftB c_{ij}\rightB$ yang didefinisikan oleh
\begin{equation*}
c_{ij}=a_{ij}+b_{ij}
\end{equation*}

\begin{example}{Penjumlahan Matriks Berukuran Sama}\label{exa:samesizematrixaddition}
Jumlahkan matriks-matriks berikut jika memungkinkan.
\begin{equation*}
A = \leftB
\begin{array}{ccc}
1 & 2 & 3 \\
1 & 0 & 4
\end{array}
\rightB,
B = \leftB
\begin{array}{rrr}
5 & 2 & 3 \\
-6 & 2 & 1
\end{array}
\rightB
\end{equation*}
\end{example}

\begin{solution}
Perhatikan bahwa $A$ dan $B$ sama-sama berukuran $2 \times 3$.
Karena $A$ dan $B$ berukuran sama, penjumlahan dapat dilakukan. Dengan menggunakan Definisi \ref{def:additionofmatrices},
penjumlahan dilakukan sebagai berikut. 
\begin{equation*}
A + B = \leftB
\begin{array}{rrr}
1 & 2 & 3 \\
1 & 0 & 4
\end{array}
\rightB
+
\leftB
\begin{array}{rrr}
5 & 2 & 3 \\
-6 & 2 & 1
\end{array}
\rightB
=\allowbreak 
\leftB
\begin{array}{rrr}
1+5 & 2+2 & 3+3 \\
1+ -6 & 0+2 & 4+1
\end{array}
\rightB
=
\leftB
\begin{array}{rrr}
6 & 4 & 6 \\
-5 & 2 & 5
\end{array}
\rightB
\end{equation*}
\end{solution}

\begin{itemize}
\item Hukum Komutatif Penjumlahan
\begin{equation}
A+B=B+A  \label{mat1}
\end{equation}

\item Hukum Asosiatif Penjumlahan
\begin{equation}
\left( A+B\right) +C=A+\left( B+C\right) \label{mat2}
\end{equation}

\item Keberadaan Identitas Aditif
\begin{equation}
\begin{array}{c}
\mbox{Terdapat matriks nol 0 sedemikian sehingga}\\
A+0=A  \label{mat3}
\end{array}
\end{equation}

\item Keberadaan Invers Aditif
\begin{equation}
\begin{array}{c}
\mbox{Terdapat matriks $-A$ sedemikian sehingga} \\
A+\left( -A\right) =0 \label{mat4}
\end{array}
\end{equation}
\end{itemize}
\end{proposition}

\ifdefined\showproofs
\begin{proof}
Perhatikan Hukum Komutatif Penjumlahan yang diberikan dalam \ref{mat1}. Misalkan $A,B,C,$ dan $D$ adalah matriks sedemikian sehingga $A+B=C$ dan
$B+A=D.$ Kita ingin menunjukkan bahwa $D=C$. Untuk melakukannya, kita akan menggunakan definisi penjumlahan matriks yang diberikan dalam Definisi \ref{def:additionofmatrices}.
Sekarang,
\begin{equation*}
c_{ij}=a_{ij}+b_{ij}=b_{ij}+a_{ij}=d_{ij}
\end{equation*}
Oleh karena itu, $C=D$ karena entri pada posisi $(i,j)$ sama untuk semua $i$ dan $j$. Perhatikan bahwa
kesimpulan ini mengikuti hukum komutatif penjumlahan bilangan, yang menyatakan bahwa jika $a$ dan $b$ adalah dua bilangan,
maka $a+b = b+a$.
Bukti untuk hasil-hasil lainnya serupa dan diserahkan sebagai latihan.
\end{proof}
\fi

\begin{outcome}
\begin{enumerate}
\item[A.] Melakukan operasi matriks berupa penjumlahan matriks, perkalian
skalar, transpos, dan perkalian matriks. Mengidentifikasi kapan
operasi-operasi ini tidak terdefinisi. Merepresentasikan operasi-operasi ini berdasarkan
entri-entri suatu matriks.

Ingat bahwa sebuah \textbf{matriks}
\index{matriks} adalah susunan bilangan berbentuk persegi panjang. Bentuk jamaknya juga
disebut \textbf{matriks}. Sebagai contoh, berikut adalah sebuah matriks.
\begin{equation}
\leftB
\begin{array}{rrrr}
1 & 2 & 3 & 4 \\
5 & 2 & 8 & 7 \\
6 & -9 & 1 & 2
\end{array}
\rightB
\label{matrix}
\end{equation}
Ingat bahwa ukuran atau dimensi suatu matriks didefinisikan sebagai $m\times n$, dengan $m$ sebagai
banyaknya baris dan $n$ sebagai banyaknya kolom. Matriks di atas adalah matriks
$3\times 4$ karena memiliki tiga baris dan empat kolom. Anda dapat mengingat bahwa kolom-kolom
menyerupai tiang pada kuil Yunani. Kolom berdiri tegak, sedangkan baris membentang
mendatar seperti alur yang dibuat traktor di ladang yang telah dibajak.

\begin{definition}{Matriks Persegi}\label{def:squarematrix}
Matriks $A$ yang berukuran $n \times n$ disebut \textbf{matriks persegi} \index{matriks!persegi}.
Dengan kata lain, $A$ adalah matriks persegi jika banyaknya baris sama dengan
banyaknya kolom.
\end{definition}

Sekarang kita memperkenalkan beberapa notasi yang khusus digunakan untuk matriks. Kita menyatakan kolom-kolom matriks $A$
dengan $A_{j}$ sebagai berikut
\begin{equation*}
A = 
\leftB
\begin{array}{rrrr}
A_{1} & A_{2} & \cdots & A_{n}
\end{array}
\rightB
\end{equation*}
Dengan demikian, $A_{j}$ adalah kolom $j$ dari $A$, jika dihitung dari kiri ke kanan.

\begin{definition}{Matriks Nol}\label{def:zeromatrix}
\textbf{Matriks nol $m\times n$} adalah matriks $m\times n$
yang setiap entrinya sama dengan nol. Matriks ini
\index{matriks nol} dinyatakan dengan $0.$
\end{definition}

\begin{example}{Matriks Nol}\label{exa:zeromatrix}
Matriks nol $2\times 3$ adalah $0= \leftB
\begin{array}{ccc}
0 & 0 & 0 \\
0 & 0 & 0
\end{array}
\rightB $.
\end{example}

\begin{definition}{Kesamaan Matriks}\label{def:equalityofmatrices}
 Misalkan $A$ dan $B$ adalah dua matriks $m \times n$. Maka $A=B$ \index{matriks!kesamaan} berarti
bahwa untuk $A=\leftB a_{ij}\rightB $
dan $B=\leftB b_{ij}\rightB ,$ berlaku $a_{ij}=b_{ij}$ untuk semua $1\leq i\leq m$ dan
$1\leq j\leq n.$
\end{definition}

Dengan kata lain, dua matriks sama persis ketika ukurannya sama dan
entri-entri yang bersesuaian identik. Oleh karena itu,
\begin{equation*}
\leftB
\begin{array}{rr}
0 & 0 \\
0 & 0 \\
0 & 0
\end{array}
\rightB \neq \leftB
\begin{array}{rr}
0 & 0 \\
0 & 0
\end{array}
\rightB
\end{equation*}
karena ukurannya berbeda. 
Selain itu,
\begin{equation*}
\leftB
\begin{array}{rr}
0 & 1 \\
3 & 2 
\end{array}
\rightB \neq \leftB
\begin{array}{rr}
1 & 0 \\
2 & 3
\end{array}
\rightB
\end{equation*}
karena, meskipun ukurannya sama, entri-entri yang bersesuaian tidak identik.

Misalkan
\begin{equation*}
A=\leftB
\begin{array}{rr}
1 & 1 \\
1 & 2
\end{array}
\rightB
\end{equation*}
seperti dalam Contoh \ref{exa:verifyinginverse}.
Untuk mencari $A^{-1}$, kita perlu mencari
matriks $\leftB
\begin{array}{rr}
x & z \\
y & w
\end{array}
\rightB $ sedemikian sehingga
\begin{equation*}
\leftB
\begin{array}{rr}
1 & 1 \\
1 & 2
\end{array}
\rightB \leftB
\begin{array}{rr}
x & z \\
y & w
\end{array}
\rightB =\leftB
\begin{array}{rr}
1 & 0 \\
0 & 1
\end{array}
\rightB 
\end{equation*}
Kita dapat mengalikan kedua matriks ini dan melihat bahwa agar persamaan tersebut benar, kita harus mencari solusi untuk sistem-sistem persamaan
\begin{equation*}
\begin{array}{c}
x+y=1 \\
x+2y=0
\end{array}
\end{equation*}
dan
\begin{equation*}
\begin{array}{c}
z+w=0 \\
z+2w=1
\end{array}
\end{equation*}
Menuliskan matriks diperbesar untuk kedua sistem ini menghasilkan
\begin{equation*}
\leftB
\begin{array}{rr|r}
1 & 1 & 1 \\
1 & 2 & 0
\end{array}
\rightB  
\label{inverse1a}
\end{equation*}
untuk sistem pertama dan
\begin{equation}
\leftB
\begin{array}{rr|r}
1 & 1 & 0 \\
1 & 2 & 1
\end{array}
\rightB  \label{inverse2a}
\end{equation}
untuk sistem kedua.

Mari selesaikan sistem pertama. Kalikan baris pertama dengan $-1$,
lalu tambahkan hasilnya ke baris kedua untuk memperoleh
\begin{equation*}
\leftB
\begin{array}{rr|r}
1 & 1 & 1 \\
0 & 1 & -1
\end{array}
\rightB
\end{equation*}
Sekarang, kalikan baris kedua dengan $-1$, lalu tambahkan hasilnya ke baris pertama untuk
memperoleh
\begin{equation*}
\leftB
\begin{array}{rr|r}
1 & 0 & 2 \\
0 & 1 & -1
\end{array}
\rightB 
\end{equation*}
Jika ditulis berdasarkan variabel, ini menyatakan $x=2$ dan $y=-1.$

Jika nilai-nilai $x,y,z,$ dan $w$ yang diperoleh
dimasukkan ke dalam matriks invers, kita melihat bahwa inversnya
adalah
\begin{equation*}
A^{-1} = 
\leftB
\begin{array}{rr}
x & z \\
y & w
\end{array}
\rightB
=
\leftB
\begin{array}{rr}
2 & -1 \\
-1 & 1
\end{array}
\rightB 
\end{equation*}

Setelah meluangkan waktu untuk menyelesaikan sistem kedua, Anda mungkin memperhatikan bahwa operasi baris yang persis sama
digunakan untuk menyelesaikan kedua sistem. Dalam setiap kasus, hasil akhirnya berbentuk
$\leftB I|X\rightB $, dengan $I$ sebagai
identitas dan $X$ memberikan satu kolom invers. Pada pembahasan di atas,
\begin{equation*}
\leftB
\begin{array}{c}
x \\
y
\end{array}
\rightB
\end{equation*}
yang merupakan kolom pertama invers diperoleh dengan menyelesaikan sistem pertama, lalu
kolom kedua
\begin{equation*}
\leftB
\begin{array}{c}
z \\
w
\end{array}
\rightB 
\end{equation*}

Untuk menyederhanakan prosedur ini, kita sebenarnya dapat menyelesaikan kedua sistem sekaligus!
Untuk melakukannya, kita dapat menulis
\begin{equation*}
\leftB
\begin{array}{rr|rr}
1 & 1 & 1 & 0 \\
1 & 2 & 0 & 1
\end{array}
\rightB
\end{equation*}

dan melakukan reduksi baris hingga diperoleh
\begin{equation*}
\leftB
\begin{array}{rr|rr}
1 & 0 & 2 & -1 \\
0 & 1 & -1 & 1
\end{array}
\rightB
\end{equation*}
lalu membaca inversnya sebagai matriks $2\times 2$ di sisi kanan.

\begin{algorithm}{Algoritma Invers Matriks}{matrixinversionalgorithm}
Misalkan $A$ adalah matriks $n\times n$. \index{matriks!mencari invers} Untuk mencari $A^{-1}$ jika ada, bentuklah
matriks diperbesar $n\times 2n$
\begin{equation*}
\leftB A|I\rightB
\end{equation*}
Jika memungkinkan, lakukan operasi baris hingga diperoleh matriks $n\times 2n$
berbentuk
\begin{equation*}
\leftB I|B\rightB  
\end{equation*}
Jika hal ini berhasil dilakukan, $B=A^{-1}.$ Dalam kasus ini, kita mengatakan bahwa $A$ \textbf{invertibel}.
Jika reduksi baris menjadi
matriks berbentuk $\leftB I|B\rightB ,$ tidak mungkin dilakukan, maka $A$ tidak memiliki invers.
\end{algorithm}

\begin{example}{Mencari Invers}\label{exa:findinginverse}
Misalkan $A=\leftB
\begin{array}{rrr}
1 & 2 & 2 \\
1 & 0 & 2 \\
3 & 1 & -1
\end{array}
\rightB $. Carilah $A^{-1}$ jika ada.
\end{example}

\begin{solution} Bentuk matriks diperbesar
\begin{equation*}
\leftB A|I\rightB =  
\leftB
\begin{array}{rrr|rrr}
1 & 2 & 2 & 1 & 0 & 0 \\
1 & 0 & 2 & 0 & 1 & 0 \\
3 & 1 & -1 & 0 & 0 & 1
\end{array}
\rightB
\end{equation*}

Sekarang kita melakukan reduksi baris dengan tujuan memperoleh matriks identitas $3 \times 3$ di sisi kiri.
Pertama, kalikan baris pertama dengan $-1 $, lalu tambahkan hasilnya ke baris kedua;
setelah itu, kalikan baris pertama dengan $-3 $ dan tambahkan hasilnya ke baris ketiga. Proses ini
menghasilkan
\begin{equation*}
\allowbreak \leftB
\begin{array}{rrr|rrr}
1 & 2 & 2 & 1 & 0 & 0 \\
0 & -2 & 0 & -1 & 1 & 0 \\
0 & -5 & -7 & -3 & 0 & 1
\end{array}
\rightB 
\end{equation*}
Kemudian, kalikan baris kedua dengan 5 dan tambahkan hasilnya ke baris ketiga yang dikalikan dengan -2.
\begin{equation*}
\leftB
\begin{array}{rrr|rrr}
1 & 2 & 2 & 1 & 0 & 0 \\
0 & -10 & 0 & -5 & 5 & 0 \\
0 & 0 & 14 & 1 & 5 & -2
\end{array}
\rightB
\end{equation*}
Selanjutnya, tambahkan baris ketiga ke baris pertama yang dikalikan dengan $ -7$.
Ini menghasilkan
\begin{equation*}
\leftB 
\begin{array}{rrr|rrr}
-7 & -14 & 0 & -6 & 5 & -2 \\
0 & -10 & 0 & -5 & 5 & 0 \\
0 & 0 & 14 & 1 & 5 & -2
\end{array}
\rightB 
\end{equation*}
Sekarang, kalikan baris kedua dengan $ -\frac{7}{5}$, lalu tambahkan hasilnya ke baris pertama.
\begin{equation*}
 \leftB
\begin{array}{rrr|rrr}
-7 & 0 & 0 & 1 & -2 & -2 \\
0 & -10 & 0 & -5 & 5 & 0 \\
0 & 0 & 14 & 1 & 5 & -2
\end{array}
\rightB 
\end{equation*}
Terakhir, bagi baris pertama dengan -7, baris kedua dengan -10, dan baris ketiga
dengan 14 sehingga diperoleh
\begin{equation*}
\leftB 
\begin{array}{rrr|rrr}
1 & 0 & 0 & -\vspace{0.05in}\frac{1}{7} & \vspace{0.05in}\frac{2}{7} & \vspace{0.05in}\frac{2}{7} \\
0 & 1 & 0 & \vspace{0.05in}\frac{1}{2} & -\vspace{0.05in}\frac{1}{2} & 0
\\
0 & 0 & 1 & \vspace{0.05in}\frac{1}{14} & \vspace{0.05in}\frac{5}{14} & -
\vspace{0.05in}\frac{1}{7}
\end{array}
\rightB 
\end{equation*}
Perhatikan bahwa sisi kiri matriks ini kini merupakan matriks identitas $3 \times 3$, yaitu $I_3$.
Oleh karena itu, inversnya adalah matriks $3 \times 3$ di sisi kanan, yang diberikan oleh
\begin{equation*}
\leftB
\begin{array}{rrr}
-\vspace{0.05in}\frac{1}{7} & \vspace{0.05in}\frac{2}{7} & \vspace{0.05in}
\frac{2}{7} \\
\vspace{0.05in}\frac{1}{2} & -\vspace{0.05in}\frac{1}{2} & 0 \\
\vspace{0.05in}\frac{1}{14} & \vspace{0.05in}\frac{5}{14} & -\vspace{0.05in}
\frac{1}{7}
\end{array}
\rightB
\end{equation*}
\end{solution}

\begin{example}{Matriks yang Tidak Memiliki Invers}\label{exa:matrixnoinverse}
Misalkan $A=\leftB
\begin{array}{rrr}
1 & 2 & 2 \\
1 & 0 & 2 \\
2 & 2 & 4
\end{array}
\rightB $. Carilah $A^{-1}$ jika ada.
\end{example}

\begin{solution} Tuliskan matriks diperbesar $\leftB A|I\rightB $
\begin{equation*}
\leftB
\begin{array}{rrr|rrr}
1 & 2 & 2 & 1 & 0 & 0 \\
1 & 0 & 2 & 0 & 1 & 0 \\
2 & 2 & 4 & 0 & 0 & 1
\end{array}
\rightB
\end{equation*}
dan lanjutkan dengan operasi baris untuk mencoba memperoleh $\leftB
I|A^{-1}\rightB .$ Kalikan baris pertama dengan $-1$, lalu tambahkan hasilnya ke
baris kedua. Kemudian, kalikan baris pertama dengan $ -2 $ dan tambahkan hasilnya ke
baris ketiga.
\begin{equation*}
\leftB 
\begin{array}{rrr|rrr}
1 & 2 & 2 & 1 & 0 & 0 \\
0 & -2 & 0 & -1 & 1 & 0 \\
0 & -2 & 0 & -2 & 0 & 1
\end{array}
\rightB
\end{equation*}
Selanjutnya, tambahkan $-1 $ kali baris kedua ke baris ketiga.
\begin{equation*}
\leftB 
\begin{array}{rrr|rrr}
1 & 2 & 2 & 1 & 0 & 0 \\
0 & -2 & 0 & -1 & 1 & 0 \\
0 & 0 & 0 & -1 & -1 & 1
\end{array}
\rightB
\end{equation*}
Pada titik ini, Anda dapat melihat bahwa tidak ada cara untuk memperoleh $I$ di
sisi kiri matriks diperbesar ini. Jadi, algoritma ini tidak mungkin
diselesaikan, sehingga invers dari $A$ tidak
ada. Dalam hal ini, kita mengatakan bahwa $A$ tidak invertibel.
\end{solution}

\begin{example}{Menggunakan Invers untuk Menyelesaikan Sistem Persamaan}\label{exa:inversetosolvesystem}
 Perhatikan sistem
persamaan berikut. Gunakan invers dari matriks yang sesuai untuk memperoleh solusi
sistem ini.
\begin{equation*}
\begin{array}{c}
x+z=1 \\
x-y+z=3 \\
x+y-z=2
\end{array}
\end{equation*}
\end{example}

\begin{solution} Pertama, kita dapat menuliskan sistem persamaan dalam bentuk matriks
\begin{equation}
AX = 
\leftB
\begin{array}{rrr}
1 & 0 & 1 \\
1 & -1 & 1 \\
1 & 1 & -1
\end{array}
\rightB \leftB
\begin{array}{r}
x \\
y \\
z
\end{array}
\rightB =\leftB
\begin{array}{r}
1 \\
3 \\
2
\end{array}
\rightB  = B  \label{inversesystem1}
\end{equation}

Invers dari matriks
\begin{equation*}
A = \leftB
\begin{array}{rrr}
1 & 0 & 1 \\
1 & -1 & 1 \\
1 & 1 & -1
\end{array}
\rightB
\end{equation*}
adalah
\begin{equation*}
A^{-1} = \leftB
\begin{array}{rrr}
0 & \vspace{0.05in}\frac{1}{2} & \vspace{0.05in}\frac{1}{2} \\
1 & -1 & 0 \\
1 & -\vspace{0.05in}\frac{1}{2} & -\vspace{0.05in}\frac{1}{2}
\end{array}
\rightB
\end{equation*}

Dari sini, solusi sistem \ref{inversesystem1} yang diberikan
diperoleh melalui
\begin{equation*}
\leftB
\begin{array}{r}
x \\
y \\
z
\end{array}
\rightB = A^{-1}B = \leftB
\begin{array}{rrr}
0 & \vspace{0.05in}\frac{1}{2} & \vspace{0.05in}\frac{1}{2} \\
1 & -1 & 0 \\
1 & -\vspace{0.05in}\frac{1}{2} & -\vspace{0.05in}\frac{1}{2}
\end{array}
\rightB \leftB
\begin{array}{r}
1 \\
3 \\
2
\end{array}
\rightB =\leftB
\begin{array}{r}
\vspace{0.05in}\frac{5}{2} \\
-2 \\
-\vspace{0.05in}\frac{3}{2}
\end{array}
\rightB 
\end{equation*}
\end{solution}

Bagaimana jika ruas kanan, yaitu $B$, dari \ref{inversesystem1} adalah $\leftB
\begin{array}{r}
0 \\
1 \\
3
\end{array}
\rightB ?$ Dengan kata lain, apa solusi dari
\begin{equation*}
\leftB
\begin{array}{rrr}
1 & 0 & 1 \\
1 & -1 & 1 \\
1 & 1 & -1
\end{array}
\rightB \leftB
\begin{array}{r}
x \\
y \\
z
\end{array}
\rightB =\leftB
\begin{array}{r}
0 \\
1 \\
3
\end{array}
\rightB ?
\end{equation*}
Berdasarkan pembahasan di atas, solusinya diberikan oleh
\begin{equation*}
\leftB
\begin{array}{r}
x \\
y \\
z
\end{array}
\rightB = A^{-1}B = \leftB
\begin{array}{rrr}
0 & \vspace{0.05in}\frac{1}{2} & \vspace{0.05in}\frac{1}{2} \\
1 & -1 & 0 \\
1 & -\vspace{0.05in}\frac{1}{2} & -\vspace{0.05in}\frac{1}{2}
\end{array}
\rightB \leftB
\begin{array}{r}
0 \\
1 \\
3
\end{array}
\rightB =\leftB
\begin{array}{r}
2 \\
-1 \\
-2
\end{array}
\rightB 
\end{equation*}
Ini menunjukkan bahwa untuk sistem $AX=B$ dengan $A^{-1}$ yang ada,
solusi mudah dicari ketika vektor $B$ diubah.
