\begin{proposition}{Hasil Kali Titik dan Sudut Apit}\label{prop:dotproductangle}
Misalkan $\vect{u}$ dan $\vect{v}$ adalah dua vektor dalam $\mathbb{R}^n$, dan misalkan
$\theta$ adalah sudut apitnya. Maka persamaan berikut berlaku.
\begin{equation*}
\vect{u}\dotprod \vect{v}=\vectlength \vect{u}\vectlength \vectlength \vect{v}
\vectlength \cos \theta
\end{equation*}
\end{proposition}

\begin{example}{Menentukan Sudut antara Dua Vektor}\label{exa:angletwovectors}
Tentukan sudut antara vektor-vektor yang diberikan oleh
\begin{equation*}
\vect{u}
=
\leftB
\begin{array}{r}
2 \\
1 \\
-1
\end{array}
\rightB,
\vect{v}
=
\leftB
\begin{array}{r}
3 \\
4 \\
1
\end{array}
\rightB
\end{equation*}
\end{example}

\begin{solution}
Berdasarkan Proposisi \ref{prop:dotproductangle},
\begin{equation*}
\vect{u}\dotprod \vect{v}=\vectlength \vect{u}\vectlength \vectlength \vect{v}
\vectlength \cos \theta
\end{equation*}
Dengan demikian,
\begin{equation*}
\cos \theta =\frac{\vect{u}\dotprod \vect{v}}{\vectlength \vect{u}\vectlength \vectlength \vect{v}
\vectlength}
\end{equation*}

Pertama, kita dapat menghitung $\vect{u}\dotprod \vect{v}$. Berdasarkan Definisi \ref{def:dotproductdefn}, hasilnya sama dengan
\begin{equation*}
\vect{u}\dotprod \vect{v}
=
(2)(3) + (1)(4)+(-1)(1) = 9
\end{equation*}

Kemudian,
\begin{equation*}
\begin{array}{c}
\vectlength \vect{u} \vectlength
=
\sqrt{(2)(2)+(1)(1)+(1)(1)}=\sqrt{6}\\
\vectlength  \vect{v} \vectlength
=
\sqrt{(3)(3)+(4)(4)+(1)(1)}=\sqrt{26}
\end{array}
\end{equation*}
Oleh karena itu, kosinus sudut apit tersebut sama dengan
\begin{equation*}
\cos \theta =\frac{9}{\sqrt{26}\sqrt{6}}=0.7205766...
\end{equation*}

Setelah kosinus diketahui, sudut dapat ditentukan dengan menghitung
kosinus invers dari nilai tersebut, yang memberikan kira-kira $\theta =0.76616$ radian.
\end{solution}

\begin{example}{Menentukan Sudut antara Dua Garis}\label{exa:anglebetweentwolines}
Tentukan sudut antara kedua garis
\begin{equation*}
L_1:  \;
\leftB
\begin{array}{r}
x \\
y \\
z
\end{array}
\rightB
 =
\leftB
\begin{array}{r}
1 \\
2 \\
0
\end{array}
\rightB +t\leftB
\begin{array}{r}
-1 \\
1 \\
2
\end{array}
\rightB
\end{equation*}
dan
\begin{equation*}
L_2: \;
\leftB
\begin{array}{r}
x \\
y \\
z
\end{array}
\rightB
 =
\leftB
\begin{array}{r}
0 \\
4 \\
-3
\end{array}
\rightB
 +s\leftB
\begin{array}{r}
2 \\
1 \\
-1
\end{array}
\rightB
\end{equation*}
\end{example}

Untuk melakukannya, pertama-tama kita mencari sudut
antara vektor-vektor arah yang diberikan di atas:
\begin{equation*}
\vect{u}=\leftB
\begin{array}{r}
-1 \\
1 \\
2
\end{array}
\rightB,\;
\vect{v}=\leftB
\begin{array}{r}
2 \\
1 \\
-1
\end{array}
\rightB
\end{equation*}

Untuk mencari sudut tersebut, kita menyelesaikan persamaan berikut terhadap $\theta$
\begin{equation*}
\vect{u}\dotprod \vect{v}=\vectlength \vect{u}\vectlength \vectlength \vect{v}
\vectlength \cos \theta
\end{equation*}
untuk memperoleh $\cos \theta = -\frac{1}{2}$ dan, karena kita memilih sudut apit
antara $0$ dan $\pi$, kita memperoleh $\theta = \frac{2 \pi}{3}$.

Sekarang sudut antara sebarang dua vektor arah untuk garis-garis ini
adalah $\frac{2 \pi}{3}$ atau komplemennya $ \phi = \pi -  \frac{2 \pi}{3}
= \frac{\pi}{3}$. Kita memilih sudut yang lebih kecil, sehingga menyimpulkan bahwa sudut antara kedua garis adalah $\frac{\pi}{3}$.
\end{solution}

\begin{example}{Menggunakan Uraian Geometris untuk Menentukan Hasil Kali Titik}\label{exa:geometricdotproduct}
Misalkan $\vect{u},\vect{v}$ adalah vektor-vektor dengan $ \vectlength \vect{u} \vectlength = 3$ dan $\vectlength \vect{v} \vectlength = 4$.
Misalkan sudut antara $\vect{u}$ dan $\vect{v}$ adalah $\pi / 3$. Tentukan $\vect{u}\dotprod \vect{v}$.
\end{example}

\begin{solution}
Dari uraian geometris hasil kali titik dalam Proposisi \ref{prop:dotproductangle},
\begin{equation*}
\vect{u}\dotprod \vect{v}=(3)(4) \cos \left( \pi / 3\right) =3\times
4\times 1/2=6
\end{equation*}
\end{solution}

\begin{proposition}{Vektor-Vektor Tegak Lurus}\label{prop:perpvectors}
Misalkan $\vect{u}$ dan $\vect{v}$ adalah vektor-vektor tak nol dalam $\mathbb{R}^n$. Maka,
$\vect{u}$ dan $\vect{v}$ disebut \textbf{tegak lurus} \index{vektor!tegak lurus} tepat ketika
\begin{equation*}
\vect{u}
\dotprod
\vect{v}
=
0
\end{equation*}
\end{proposition}

\begin{example}{Menentukan Apakah Dua Vektor Tegak Lurus}\label{exa:perpendicularvectors}
Tentukan apakah kedua vektor,
\begin{equation*}
\vect{u}=
\leftB
\begin{array}{r}
2 \\
1 \\
-1
\end{array}
\rightB,
\vect{v}
=
\leftB
\begin{array}{r}
1 \\
3 \\
5
\end{array}
\rightB
\end{equation*}
tegak lurus.
\end{example}

\begin{solution}
Untuk menentukan apakah kedua vektor ini tegak lurus, kita menghitung hasil kali titiknya.
Hasilnya diberikan oleh
\begin{equation*}
\vect{u} \dotprod \vect{v}
=
(2)(1) + (1)(3) + (-1)(5)
=
0
\end{equation*}
Oleh karena itu, berdasarkan Proposisi \ref{prop:perpvectors}, kedua vektor ini tegak lurus.
\end{solution}

Terdapat dua cara mengalikan vektor yang sangat penting dalam
penerapan. Cara pertama disebut \textbf{hasil kali titik}. Ketika kita mengambil hasil kali titik vektor, hasilnya
adalah sebuah skalar. Karena alasan ini, hasil kali titik juga
disebut \textbf{hasil kali skalar} dan terkadang \textbf{hasil kali dalam}. Definisinya adalah sebagai berikut.
\index{hasil kali titik}
\index{hasil kali skalar}
\index{hasil kali dalam}

\begin{definition}{Hasil Kali Titik}\label{def:dotproductdefn}
Misalkan $\vect{u},\vect{v}$ adalah dua vektor dalam $\mathbb{R}^{n}$. Maka kita
mendefinisikan \textbf{hasil kali titik} $\vect{u}\dotprod \vect{v}$ sebagai
\begin{equation*}
\vect{u}\dotprod \vect{v} = \sum_{k=1}^{n}u_{k}v_{k}
\end{equation*}
\end{definition}

\begin{example}{Menghitung Hasil Kali Titik}\label{exa:dotproduct}
Tentukan $\vect{u} \dotprod \vect{v}$ untuk
\begin{equation*}
\vect{u}
=
\begin{bmatrix}
1 \\
2 \\
0 \\
-1
\end{bmatrix},
\vect{v}
=
\begin{bmatrix}
0 \\
1 \\
2 \\
3
\end{bmatrix}
\end{equation*}
\end{example}

\begin{solution}
Berdasarkan Definisi \ref{def:dotproductdefn}, kita harus menghitung
\begin{equation*}
\vect{u}\dotprod \vect{v} = \sum_{k=1}^{4}u_{k}v_{k}
\end{equation*}

Hasilnya diberikan oleh
\begin{eqnarray*}
\vect{u} \dotprod \vect{v}
&=&
(1)(0) + (2)(1) + (0)(2) + (-1)(3) \\
&=&
0 + 2 + 0 + -3 \\
&=&
-1
\end{eqnarray*}
\end{solution}

Berdasarkan definisi ini, terdapat beberapa sifat penting yang dipenuhi
oleh hasil kali titik.
\index{hasil kali titik!sifat-sifat}

\begin{example}{Panjang Vektor}\label{exa:dotproductlength}
Tentukan panjang
\begin{equation*}
\vect{u}
=
\leftB
\begin{array}{r}
2 \\
1 \\
4 \\
2
\end{array}
\rightB
\end{equation*}
Dengan kata lain, tentukan $\vectlength \vect{u} \vectlength .$ 
\end{example}

Hasilnya diberikan oleh
\begin{eqnarray*}
\vect{u} \dotprod \vect{u}
&=&
(2)(2) + (1)(1) + (4)(4) + (2)(2) \\
&=&
4 + 1 + 16 + 4 \\
&=&
25
\end{eqnarray*}

Kemudian,
\begin{eqnarray*}
\vectlength \vect{u} \vectlength
&=& \sqrt {\vect{u} \dotprod \vect{u}} \\
&=& \sqrt{25} \\
&=& 5
\end{eqnarray*}
\end{solution}

\begin{theorem}{Ketaksamaan Cauchy--Schwarz}\label{thm:cauchyschwarzinequality}
Hasil kali titik memenuhi ketaksamaan
\begin{equation}
\left\vert \vect{u}\dotprod \vect{v}\right\vert \leq \vectlength \vect{u}\vectlength \vectlength \vect{v}\vectlength   \label{cauchy}
\end{equation}
Lebih lanjut, kesamaan diperoleh jika dan hanya jika salah satu dari $\vect{u}$ atau $\vect{v}$ merupakan kelipatan skalar dari yang lain.
\end{theorem}

\ifdefined\showproofs
\begin{proof}
Pertama, perhatikan bahwa jika $\vect{v}=\vect{0}$, kedua ruas \ref{cauchy}
sama dengan nol sehingga ketaksamaan berlaku dalam kasus ini. Oleh karena itu, dalam pembahasan berikut
kita akan mengasumsikan bahwa $\vect{v}\neq \vect{0}$.

Definisikan sebuah fungsi dari $t\in \mathbb{R}$ dengan
\begin{equation*}
f\left( t\right) =\left( \vect{u}+t\vect{v}\right) \dotprod \left( \vect{u}+
t\vect{v}\right)
\end{equation*}
Maka, berdasarkan Proposisi \ref{prop:propertiesdotproduct}, $f\left( t\right) \geq 0$ untuk semua $t\in \mathbb{R}$.
Juga dari Proposisi \ref{prop:propertiesdotproduct},
\begin{eqnarray*}
f\left( t\right) &=&\vect{u}\dotprod \left( \vect{u}+t\vect{v}\right) +
t\vect{v}\dotprod \left( \vect{u}+t\vect{v}\right) \\
&=&\vect{u}\dotprod \vect{u}+t\left( \vect{u}\dotprod \vect{v}\right) + t \vect{v}\dotprod \vect{u}+
t^{2}\vect{v}\dotprod \vect{v} \\
&=&\vectlength \vect{u}\vectlength ^{2}+2t\left( \vect{u}\dotprod \vect{v}\right) +\vectlength
\vect{v}\vectlength ^{2}t^{2}
\end{eqnarray*}

\begin{theorem}{Ketaksamaan Segitiga}\label{thm:triangleinequalitydotproduct}
Untuk $\vect{u},\vect{v}\in \mathbb{R}^{n}$,
\begin{equation}
\vectlength \vect{u}+\vect{v}\vectlength \leq \vectlength \vect{u}\vectlength +\vectlength \vect{v}
\vectlength  \label{triangleineq1}
\end{equation}
dan kesamaan berlaku jika dan hanya jika salah satu vektor merupakan kelipatan skalar tak negatif dari vektor lainnya.

Selain itu,
\begin{equation}
| \vectlength \vect{u}\vectlength -\vectlength \vect{v}\vectlength | \leq
\vectlength \vect{u}-\vect{v}\vectlength  \label{triangleineq2}
\end{equation}
\end{theorem}

\ifdefined\showproofs
\begin{proof} Berdasarkan sifat-sifat hasil kali titik dan ketaksamaan Cauchy--Schwarz,
\begin{eqnarray*}
\vectlength \vect{u}+\vect{v}\vectlength ^{2} &=& \left( \vect{u}+\vect{v}\right) \dotprod \left( \vect{u}+\vect{v}\right) \\
& =&\left( \vect{u}\dotprod \vect{u}\right) +\left( \vect{u}\dotprod \vect{v}\right) +\left(\vect{v}\dotprod \vect{u}\right) +\left( \vect{v}\dotprod \vect{v}\right) \\
&=&\vectlength \vect{u}\vectlength ^{2}+2\left( \vect{u}\dotprod \vect{v}\right)+\vectlength \vect{v}\vectlength ^{2} \\
&\leq& \vectlength \vect{u}\vectlength ^{2}+2\left\vert \vect{u}\dotprod \vect{v}\right\vert +\vectlength \vect{v}\vectlength ^{2} \\
&\leq& \vectlength \vect{u}\vectlength ^{2}+2\vectlength \vect{u}\vectlength \vectlength \vect{v}\vectlength +\vectlength \vect{v}\vectlength ^{2} =\left( \vectlength \vect{u}\vectlength +\vectlength \vect{v}\vectlength\right) ^{2}
\end{eqnarray*}
Jadi,
\begin{equation*}
\vectlength \vect{u}+\vect{v}\vectlength ^{2} \leq \left( \vectlength \vect{u}\vectlength +\vectlength \vect{v}\vectlength
\right) ^{2}
\end{equation*}
Dengan mengambil akar kuadrat kedua ruas, Anda memperoleh \ref{triangleineq1}.

Untuk memperoleh bentuk lain ketaksamaan segitiga, tuliskan
\begin{equation*}
\vect{u}=\vect{u}-\vect{v}+\vect{v}
\end{equation*}
sehingga
\begin{align*}
\vectlength \vect{u}\vectlength & =\vectlength \vect{u}-\vect{v}+\vect{v}\vectlength \\
& \leq \vectlength \vect{u}-\vect{v}\vectlength +\vectlength \vect{v}\vectlength
\end{align*}
Oleh karena itu,
\begin{equation}
\vectlength \vect{u}\vectlength -\vectlength \vect{v}\vectlength \leq \vectlength \vect{u}-\vect{v}
\vectlength  \label{triangleineq3}
\end{equation}
Demikian pula,
\begin{equation}
\vectlength \vect{v}\vectlength -\vectlength \vect{u}\vectlength \leq \vectlength \vect{v}-\vect{u}
\vectlength =\vectlength \vect{u}-\vect{v}\vectlength  \label{triangleineq4}
\end{equation}
Dari \ref{triangleineq3} dan \ref{triangleineq4}, diperoleh bahwa \ref{triangleineq2} berlaku. Hal ini
karena $\left| \vectlength \vect{u}\vectlength -\vectlength \vect{v}\vectlength
\right| $ sama dengan ruas kiri dari \ref{triangleineq3} atau \ref{triangleineq4}, dan
dalam kedua keadaan, $\left| \vectlength \vect{u}\vectlength -\vectlength \vect{v}\vectlength
\right| \leq \vectlength \vect{u}-\vect{v}\vectlength $.
\end{proof}
\fi

Pertama, kita akan membahas konsep jarak untuk $\mathbb{R}$, yaitu untuk titik-titik dalam $\mathbb{R}^1$.
Di sini,
jarak antara dua titik $P$ dan $Q$ diberikan oleh nilai mutlak
selisih keduanya. Kita menyatakan jarak antara $P$ dan $Q$ dengan $d(P,Q)$, yang didefinisikan sebagai
\begin{equation}
d(P,Q) = \sqrt{ \left( P-Q\right) ^{2}}
\label{distance1}
\end{equation}

\begin{picture}(1,100)
\put(100,20){\begin{picture}(1,1)
\setlength{\unitlength}{2pt}
\thicklines
\qbezier[10](0,0)(25,0)(50,0)
\qbezier[7](0,0)(0,15)(0,30)
\qbezier[10](0,30)(25,30)(50,30)
