\draw[fill=red](2,1) circle [radius=3pt];
\node[below right] at (4,0){$x$};
\node[left] at(0,5){$y$};
\node[below] at (-3,-0.5){$-3$};
\node[below] at (2,-0.5){$2$};
\node[left] at (-0.5, 1){$1$};
\node[left] at (-0.5, 4){$4$};
