p_1 & p_2 & p_3 \end{array}\rightB ^T$};
\node[below] at (-1,1,0){$A$};
\node[below] at (0.5,2,0){$B$};
\end{tikzpicture}\par\captionof{figure}{Diagram tiga dimensi dengan dua panah biru sejajar yang sama panjang dan searah: vektor posisi...}\label{fig:RnVectorsRn-tikz03}% fig-num-auto

\begin{definition}{Vektor dalam $\mathbb{R}^n$}\label{def:vectorsRn}
Misalkan $\mathbb{R}^{n} = \left\{ \left( x_{1}, \cdots, x_{n}\right)
:x_{j}\in \mathbb{R}\text{ untuk }j=1,\cdots ,n\right\} .$ Maka,
\begin{equation*}
\vect{x}
=
\leftB \begin{array}{c}
x_{1} \\
\vdots \\
x_{n}
\end{array}
\rightB
\end{equation*}
disebut sebuah \textbf{vektor}. Vektor memiliki besar (magnitudo) sekaligus arah.
Bilangan-bilangan $x_{j}$ disebut \textbf{komponen} dari $\vect{x}$.
\index{vektor!komponen}
\index{vektor}
\end{definition}

Kita mengakhiri bagian ini dengan pembahasan singkat mengenai notasi. Dalam bagian-bagian sebelumnya, kita telah menulis vektor sebagai kolom, atau matriks $n \times 1$. Demi kemudahan dalam bab ini, kita dapat menulis vektor sebagai transpos vektor baris, atau matriks $1 \times n$. Keduanya tentu saja setara dan kita dapat beralih di antara kedua notasi tersebut. Oleh karena itu, pahamilah bahwa
\[
\leftB
\begin{array}{r}
2 \\
3
\end{array}
\rightB  = \leftB
\begin{array}{rr}
2 & 3
\end{array}
\rightB^T
\]

Perhatikan bahwa dua vektor $\vect{u} = \leftB u_{1} \cdots u_{n}\rightB^T $ dan
$\vect{v}=\leftB v_{1} \cdots v_{n}\rightB^T$ sama jika dan hanya jika
semua komponen yang bersesuaian sama. Secara tepat,
\begin{equation*}
\begin{array}{c}
\vect{u}=\vect{v} \; \mbox{jika dan hanya jika}\\
u_{j}=v_{j} \; \mbox{untuk semua}\; j=1,\cdots ,n
\end{array}
\end{equation*}
Jadi,
$\leftB
\begin{array}{rrr}
1  & 2 & 4
\end{array}
\rightB^T \in \mathbb{R}^{3}$ dan $\leftB
\begin{array}{rrr}
2 & 1 & 4
\end{array}
\rightB^T \in
\mathbb{R}^{3}$, tetapi $\leftB
\begin{array}{rrr}
1 & 2 & 4
\end{array}
\rightB^T \neq \leftB
\begin{array}{rrr}
2 & 1 & 4
\end{array}
\rightB^T $ karena,
meskipun melibatkan bilangan-bilangan yang sama, urutan bilangan-bilangan tersebut berbeda.

Untuk kasus khusus $\mathbb{R}^3$, terdapat tiga vektor istimewa yang sering kita gunakan.
Vektor-vektor tersebut diberikan oleh
\begin{equation*}
\vect{i} =
\leftB
\begin{array}{rrr}
1 & 0 & 0
\end{array}
\rightB^T
\end{equation*}
\begin{equation*}
\vect{j} =
\leftB
\begin{array}{rrr}
0 & 1 & 0
\end{array}
\rightB^T
\end{equation*}
\begin{equation*}
\vect{k} =
\leftB
\begin{array}{rrr}
0 & 0 & 1
\end{array}
\rightB^T
\end{equation*}
Kita dapat menulis sebarang vektor $\vect{u} =
\leftB
\begin{array}{rrr}
u_1 & u_2 & u_3
\end{array}
\rightB^T$
sebagai kombinasi linear vektor-vektor ini, yang ditulis sebagai $\vect{u} = u_1 \vect{i} + u_2 \vect{j} + u_3 \vect{k}$. Notasi ini akan digunakan di seluruh
bab ini.

Sekarang misalkan kita memiliki vektor $\vect{u} = \leftB
\begin{array}{lll}
u_1 &  u_2 & u_3
\end{array}
\rightB^T$ dan kita mengalikan $\vect{u}$ dengan suatu
skalar $k$. Berdasarkan Definisi \ref{def:vectorscalarmultiplication},
$k\vect{u} = \leftB
\begin{array}{rrr}
ku_{1} & ku_{2} & ku_{3}
\end{array}
\rightB^T $.
Kemudian, dengan menggunakan Definisi \ref{def:distancebetweenpoints}, panjang vektor ini diberikan oleh
\begin{equation*}
\sqrt{\left( \left( k u_{1}\right) ^{2}+\left( k u_{2}\right)
^{2}+\left( k u_{3}\right) ^{2}\right) }=\left\vert k \right\vert
\sqrt{u_{1}^{2}+u_{2}^{2}+u_{3}^{2}}
\end{equation*}
Jadi, hubungan berikut berlaku.
\begin{equation*}
\vectlength k \vect{u} \vectlength =\left\vert k \right\vert
\vectlength \vect{u} \vectlength
\end{equation*}
Dengan kata lain, perkalian dengan suatu skalar memperbesar atau memperkecil panjang
vektor dengan faktor $\left\vert k \right\vert$. Jika $\left\vert k \right\vert > 1$, panjang vektor yang dihasilkan akan
diperbesar. Jika $\left\vert k \right\vert <1$, panjang vektor yang dihasilkan akan menyusut. Ingat bahwa berdasarkan definisi
nilai mutlak, $\left\vert k \right\vert >0$.

