\modelhead{Model}
\begin{align*}
\min \quad & z = 10x_1 + 16x_2 + 5s_1 + 5s_2   \tag{Total cost} \\
\st        & s_0 + x_1 = 10 + s_1   \tag{Day 1 balance} \\
& s_1 + x_2 = 4 + s_2   \tag{Day 2 balance} \\
& x_1, x_2, s_0, s_1, s_2 \geq 0.   \tag{Non-negativity constraints}
\end{align*}

