\begin{itemize}
\item \( \text{inv}_i \): investment required for project \( i \)
\item \( \text{ret}_i \): projected return from project \( i \)
\item \( B = 100{,}000 \): total available capital
\end{itemize}

target_text:
\smallskip \modelhead{Parameter}
\begin{itemize}
\item \( \text{inv}_i \): investasi yang dibutuhkan untuk proyek \( i \)
\item \( \text{ret}_i \): proyeksi imbal hasil dari proyek \( i \)
\item \( B = 100{,}000 \): total modal yang tersedia
\end{itemize}

source_text:
\begin{align*}
\max \quad & \sum_{i \in P} \text{ret}_i \cdot x_i \\
\st        & \sum_{i \in P} \text{inv}_i \cdot x_i \le B \\
& x_i \in \{0,1\} &&\quad \text{for all } i \in P
\end{align*}

target_text:
