source_text:
\modelhead{Sets}
\begin{itemize}
    \item \(t \in \{1,2,\dots,T\}\): Periods in the planning horizon.
\end{itemize}

target_text:
\modelhead{Himpunan}
\begin{itemize}
    \item \(t \in \{1,2,\dots,T\}\): Periode-periode dalam cakrawala perencanaan.
\end{itemize}

source_text:
\modelhead{Parameters}
\begin{itemize}
    \item \(c^{prod}_t\): Production cost per unit in period \(t\) (for \(t=1,\dots,T\)).
    \item \(c^{inv}\): Inventory holding cost per unit carried from one period to the next.
    \item \(d_t\): Demand in period \(t\).
    \item \(s_0\): Initial inventory available at the start of period 1.
\end{itemize}

target_text:
\modelhead{Parameter}
\begin{itemize}
    \item \(c^{prod}_t\): Biaya produksi per unit pada periode \(t\) (untuk \(t=1,\dots,T\)).
    \item \(c^{inv}\): Biaya penyimpanan persediaan per unit yang dibawa dari satu periode ke periode berikutnya.
    \item \(d_t\): Permintaan pada periode \(t\).
    \item \(s_0\): Persediaan awal yang tersedia pada awal periode 1.
\end{itemize}

source_text:
\modelhead{Variables}
\begin{itemize}
    \item \(x_t\): Number of units produced in period \(t\).
    \item \(s_t\): Inventory level at the end of period \(t\).
\end{itemize}

target_text:
\modelhead{Variabel}
\begin{itemize}
    \item \(x_t\): Jumlah unit yang diproduksi pada periode \(t\).
    \item \(s_t\): Tingkat persediaan pada akhir periode \(t\).
\end{itemize}

source_text:
\modelhead{Model}
\begin{align*}
\min_{x,s} \quad & z = \sum_{t=1}^{T} \Big( c^{prod}_t\, x_t + c^{inv}\, s_t \Big)   \tag{Total cost} \\
\st        & s_0 + x_1 = d_1 + s_1   \tag{Period 1 balance} \\
                 & s_{t-1} + x_t = d_t + s_t &&\quad \text{for all } t=2,\dots,T   \tag{Inventory balance} \\
                 & x_t \geq 0,\quad s_t \geq 0 &&\quad \text{for all } t=1,\dots,T.
\end{align*}

target_text:
\modelhead{Model}
\begin{align*}
\min_{x,s} \quad & z = \sum_{t=1}^{T} \Big( c^{prod}_t\, x_t + c^{inv}\, s_t \Big)   \tag{Biaya total} \\
\st        & s_0 + x_1 = d_1 + s_1   \tag{Keseimbangan periode 1} \\
                 & s_{t-1} + x_t = d_t + s_t &&\quad \text{untuk semua } t=2,\dots,T   \tag{Keseimbangan persediaan} \\
                 & x_t \geq 0,\quad s_t \geq 0 &&\quad \text{untuk semua } t=1,\dots,T.
\end{align*}

