source_text:
The transportation network consists of:
\begin{itemize}
    \item \textbf{Two warehouses} (supply nodes) that store goods: 
          \begin{itemize}
              \item \textbf{Warehouse 1} can supply up to 20 units.
              \item \textbf{Warehouse 2} can supply up to 30 units.
          \end{itemize}
    \item \textbf{Two retail stores} (demand nodes) that require goods:
          \begin{itemize}
              \item \textbf{Store 1} requires 25 units.
              \item \textbf{Store 2} requires 25 units.
          \end{itemize}
    \item Transportation routes (\textbf{arcs}) connecting warehouses to stores, each with a transportation cost per unit and capacity limit.
\end{itemize}

target_text:
Jaringan transportasi tersebut terdiri atas:
\begin{itemize}
    \item \textbf{Dua gudang} (simpul pasokan) yang menyimpan barang:
          \begin{itemize}
              \item \textbf{Gudang 1} dapat memasok paling banyak 20 unit.
              \item \textbf{Gudang 2} dapat memasok paling banyak 30 unit.
          \end{itemize}
    \item \textbf{Dua toko ritel} (simpul permintaan) yang membutuhkan barang:
          \begin{itemize}
              \item \textbf{Toko 1} membutuhkan 25 unit.
              \item \textbf{Toko 2} membutuhkan 25 unit.
          \end{itemize}
    \item Rute transportasi (\textbf{busur}) yang menghubungkan gudang dengan toko; setiap rute memiliki biaya transportasi per unit dan batas kapasitas.
\end{itemize}

source_text:
\begin{itemize}
    \item \( V = \{ W_1, W_2, S_1, S_2 \} \) (two warehouses and two stores).
    \item \( A = \{(W_1, S_1), (W_1, S_2), (W_2, S_1), (W_2, S_2)\} \) (directed transportation routes).
    \item Each arc \( (i,j) \) has a given transportation cost \( c_{ij} \) and capacity \( u_{ij} \).
\end{itemize}

target_text:
\begin{itemize}
    \item \( V = \{ W_1, W_2, S_1, S_2 \} \) (dua gudang dan dua toko).
    \item \( A = \{(W_1, S_1), (W_1, S_2), (W_2, S_1), (W_2, S_2)\} \) (rute transportasi berarah).
    \item Setiap busur \( (i,j) \) memiliki biaya transportasi \( c_{ij} \) dan kapasitas \( u_{ij} \) tertentu.
\end{itemize}

source_text:
\begin{align}
\min \quad & 4x_{W_1,S_1} + 6x_{W_1,S_2} + 5x_{W_2,S_1} + 2x_{W_2,S_2}\label{eq:example_objective} \\
    \st \quad
    & x_{W_1,S_1} + x_{W_1,S_2} \leq 20   \tag{Supply constraint for Warehouse 1}\label{eq:supply1} \\
    & x_{W_2,S_1} + x_{W_2,S_2} \leq 30   \tag{Supply constraint for Warehouse 2}\label{eq:supply2} \\
    & x_{W_1,S_1} + x_{W_2,S_1} = 25   \tag{Demand constraint for Store 1}\label{eq:demand1} \\
    & x_{W_1,S_2} + x_{W_2,S_2} = 25   \tag{Demand constraint for Store 2}\label{eq:demand2} \\
    & 0 \leq x_{ij} \leq u_{ij} &&\quad \text{for all } (i,j) \in A.\label{eq:capacity_constraint_example}
\end{align}

target_text:
\begin{align}
\min \quad & 4x_{W_1,S_1} + 6x_{W_1,S_2} + 5x_{W_2,S_1} + 2x_{W_2,S_2}\label{eq:example_objective} \\
    \st \quad
    & x_{W_1,S_1} + x_{W_1,S_2} \leq 20   \tag{Kendala pasokan untuk Gudang 1}\label{eq:supply1} \\
    & x_{W_2,S_1} + x_{W_2,S_2} \leq 30   \tag{Kendala pasokan untuk Gudang 2}\label{eq:supply2} \\
    & x_{W_1,S_1} + x_{W_2,S_1} = 25   \tag{Kendala permintaan untuk Toko 1}\label{eq:demand1} \\
    & x_{W_1,S_2} + x_{W_2,S_2} = 25   \tag{Kendala permintaan untuk Toko 2}\label{eq:demand2} \\
    & 0 \leq x_{ij} \leq u_{ij} &&\quad \text{untuk semua } (i,j) \in A.\label{eq:capacity_constraint_example}
\end{align}

