source_text:
\modelhead{Sets and Parameters}
\begin{itemize}
\item Let $R$ be the set of demand regions, with demand $d_r$.
\item Let $P_r$ be the set of feasible fulfillment paths for region $r$ (a path uses specific facilities and transportation arcs); $c_p$ is the cost of serving one unit along path $p$.
\item Let $A$ be the set of arcs with capacities $u_a$.
\end{itemize}

target_text:
\modelhead{Himpunan dan Parameter}
\begin{itemize}
\item Misalkan $R$ adalah himpunan kawasan permintaan, dengan permintaan $d_r$.
\item Misalkan $P_r$ adalah himpunan lintasan pemenuhan yang layak untuk kawasan $r$ (sebuah lintasan menggunakan fasilitas dan busur transportasi tertentu); $c_p$ adalah biaya untuk melayani satu unit melalui lintasan $p$.
\item Misalkan $A$ adalah himpunan busur dengan kapasitas $u_a$.
\end{itemize}

source_text:
\modelhead{Variables}
\begin{itemize}
\item Let $f_p \geq 0$ be the volume served on path $p$.
\item Let $w_a = 1$ if arc $a$ is operated (a connection Amazon chooses to run).
\end{itemize}

target_text:
\modelhead{Variabel}
\begin{itemize}
\item Misalkan $f_p \geq 0$ adalah volume yang dilayani melalui lintasan $p$.
\item Misalkan $w_a = 1$ jika busur $a$ dioperasikan (koneksi yang dipilih Amazon untuk dijalankan).
\end{itemize}

source_text:
\modelhead{Model}
\begin{align*}
\min \quad & \sum_{p} c_p\, f_p + \sum_{a \in A} g_a\, w_a   \tag{flow cost + cost of operating connections} \\
\st        & \sum_{p \in P_r} f_p = d_r &&\quad \text{for all } r \in R   \tag{serve all demand} \\
           & \sum_{p \,\ni\, a} f_p \leq u_a\, w_a &&\quad \text{for all } a \in A   \tag{use only open connections, within capacity} \\
           & f_p \geq 0, \quad w_a \in \{0,1\}.
\end{align*}

target_text:
\modelhead{Model}
\begin{align*}
\min \quad & \sum_{p} c_p\, f_p + \sum_{a \in A} g_a\, w_a   \tag{biaya aliran + biaya pengoperasian koneksi} \\
\st        & \sum_{p \in P_r} f_p = d_r &&\quad \text{untuk semua } r \in R   \tag{layani seluruh permintaan} \\
           & \sum_{p \,\ni\, a} f_p \leq u_a\, w_a &&\quad \text{untuk semua } a \in A   \tag{gunakan hanya koneksi terbuka, dalam batas kapasitas} \\
           & f_p \geq 0, \quad w_a \in \{0,1\}.
\end{align*}

source_text:
\subsection*{Assumptions and Simplifications}
\begin{itemize}
\item Demands $d_r$ and travel times are forecasts, produced by machine learning models; the optimization treats them as data.
\item The deployed system also has a time-expanded ``network timing'' model producing hourly schedules; the topology model above is the strategic layer.
\end{itemize}

target_text:
\subsection*{Asumsi dan Penyederhanaan}
\begin{itemize}
\item Permintaan $d_r$ dan waktu tempuh merupakan ramalan yang dihasilkan oleh model pembelajaran mesin; optimasi memperlakukannya sebagai data.
\item Sistem yang diterapkan juga memiliki model ``waktu jaringan'' berdimensi waktu yang menghasilkan jadwal per jam; model topologi di atas merupakan lapisan strategis.
\end{itemize}

