\begin{theorem}{Representation Theorem}
\label{thm:representation}
 Let \( P \subseteq \mathbb{R}^n \) be a nonempty polyhedron, let $\mathbf{x}^1, \mathbf{x}^2,\cdots \mathbf{x}^k$ be the set of extreme points of $P$, and if $P$ is unbounded, $\mathbf{d}^1, \mathbf{d}^2,\cdots \mathbf{d}^l$ be the set of extreme directions. Then any $\mathbf{x} \in P$ is equal to a convex combination of the extreme points and a non-negative linear combination of the extreme directions: $\mathbf{x} = \sum_{j=1}^k \lambda_j \mathbf{x}^j + \sum_{j=1}^l \mu_j \mathbf{d}^j$, where $\sum_{j=1}^k \lambda_j = 1$, $\lambda_j \ge 0,~\forall  j=1,2,\cdots,k$, and $\mu_j \ge 0,~\forall j=1,2,\cdots,l$.
 \end{theorem}

target_text:
\begin{theorem}{Teorema Representasi}
\label{thm:representation}
 Misalkan \( P \subseteq \mathbb{R}^n \) adalah polihedron tak kosong, misalkan $\mathbf{x}^1, \mathbf{x}^2,\cdots \mathbf{x}^k$ adalah himpunan titik ekstrem $P$, dan jika $P$ tak berbatas, misalkan $\mathbf{d}^1, \mathbf{d}^2,\cdots \mathbf{d}^l$ adalah himpunan arah ekstremnya. Maka setiap $\mathbf{x} \in P$ sama dengan kombinasi konveks titik-titik ekstrem dan kombinasi linier tak negatif arah-arah ekstrem: $\mathbf{x} = \sum_{j=1}^k \lambda_j \mathbf{x}^j + \sum_{j=1}^l \mu_j \mathbf{d}^j$, dengan $\sum_{j=1}^k \lambda_j = 1$, $\lambda_j \ge 0,~\forall  j=1,2,\cdots,k$, dan $\mu_j \ge 0,~\forall j=1,2,\cdots,l$.
 \end{theorem}

