\begin{ex}{Vector Operations}{}
\label{ex:vector-operations}
\stars{1}Let \( \mathbf{v} = [3, -2, 4] \) and \( \mathbf{u} = [-1, 0, 2] \). Compute:
\begin{enumerate}
    \item \( \mathbf{v} + \mathbf{u} \)
    \item \( 2\mathbf{v} \)
    \item \( \mathbf{v} \cdot \mathbf{u} \)
\end{enumerate}
\exrefs{\S\ref{sec:math-preliminaries}}
\end{ex}

target_text:
