source_text:
\begin{ex}{Convex or Not?}{}
\label{ex:convex-or-not}
\stars{1}For each of the following subsets of \( \mathbb{R}^2 \), decide whether the set is convex, as in Figures~\ref{fig:convex-set-example} and \ref{fig:nonconvex-set-example}. If the set is not convex, exhibit two points in the set whose connecting segment leaves the set.
\begin{enumerate}
    \item The disk \( D = \{ \mathbf{x} : x_1^2 + x_2^2 \leq 4 \} \).
    \item The ring \( R = \{ \mathbf{x} : 1 \leq x_1^2 + x_2^2 \leq 4 \} \).
    \item The halfspace \( H = \{ \mathbf{x} : x_1 + 2x_2 \leq 3 \} \).
    \item The set \( S = \{ \mathbf{x} : |x_1| \geq 1 \} \).
\end{enumerate}
\exrefs{\S\ref{sec:convexity}}
\end{ex}

target_text:
\begin{ex}{Konveks atau Tidak?}{}
\label{ex:convex-or-not}
\stars{1}Untuk setiap subhimpunan \( \mathbb{R}^2 \) berikut, tentukan apakah himpunan tersebut konveks, seperti pada Gambar~\ref{fig:convex-set-example} dan \ref{fig:nonconvex-set-example}. Jika himpunan tersebut tidak konveks, berikan dua titik dalam himpunan yang ruas penghubungnya keluar dari himpunan.
\begin{enumerate}
    \item Cakram \( D = \{ \mathbf{x} : x_1^2 + x_2^2 \leq 4 \} \).
    \item Cincin \( R = \{ \mathbf{x} : 1 \leq x_1^2 + x_2^2 \leq 4 \} \).
    \item Setengah ruang \( H = \{ \mathbf{x} : x_1 + 2x_2 \leq 3 \} \).
    \item Himpunan \( S = \{ \mathbf{x} : |x_1| \geq 1 \} \).
\end{enumerate}
\exrefs{\S\ref{sec:convexity}}
\end{ex}

source_text:
\begin{ex}{Writing an LP in Matrix Notation}{}
\label{ex:lp-matrix-notation}
\stars{1}Consider the linear program
\begin{align*}
\max \quad & 3x_1 + 2x_2\\
\text{s.t.} \quad & x_1 + 3x_2 \leq 6\\
& 2x_1 + x_2 \leq 4\\
& x_1, x_2 \geq 0.
\end{align*}
Write this LP in the standard form \( \max\{ \mathbf{c}^\top \mathbf{x} : A\mathbf{x} \leq \mathbf{b} \} \) used in this chapter: give the vector \( \mathbf{c} \), the \( 4 \times 2 \) matrix \( A \), and the vector \( \mathbf{b} \). (Write each nonnegativity constraint \( x_i \geq 0 \) as \( -x_i \leq 0 \).) Then verify that the point \( \mathbf{x} = (1.2, 1.6) \) satisfies \( A\mathbf{x} \leq \mathbf{b} \).
\exrefs{\S\ref{sec:math-preliminaries}, \S\ref{sec:algebraic-vertex-proof}}
\end{ex}

target_text:
\begin{ex}{Menulis Program Linier dalam Notasi Matriks}{}
\label{ex:lp-matrix-notation}
\stars{1}Perhatikan program linier
\begin{align*}
\max \quad & 3x_1 + 2x_2\\
\text{dengan syarat} \quad & x_1 + 3x_2 \leq 6\\
& 2x_1 + x_2 \leq 4\\
& x_1, x_2 \geq 0.
\end{align*}
Tulislah program linier ini dalam bentuk standar \( \max\{ \mathbf{c}^\top \mathbf{x} : A\mathbf{x} \leq \mathbf{b} \} \) yang digunakan dalam bab ini: berikan vektor \( \mathbf{c} \), matriks berukuran \( 4 \times 2 \), yaitu \( A \), dan vektor \( \mathbf{b} \). (Tuliskan setiap kendala ketaknegatifan \( x_i \geq 0 \) sebagai \( -x_i \leq 0 \).) Kemudian verifikasi bahwa titik \( \mathbf{x} = (1.2, 1.6) \) memenuhi \( A\mathbf{x} \leq \mathbf{b} \).
\exrefs{\S\ref{sec:math-preliminaries}, \S\ref{sec:algebraic-vertex-proof}}
\end{ex}

source_text:
\begin{ex}{Convex Combinations and Geometry}{}
\label{ex:convex-combo-triangle}
\stars{2}Let \( P \) be the triangle with vertices at \( (0,0) \), \( (2,0) \), and \( (0,2) \).
\begin{enumerate}
    \item Plot the set \( P \).
    \item Determine whether the point \( (1,1) \) is a convex combination of the vertices.
    \item Determine whether the point \( (1.5,1.5) \) is in \( P \).
\end{enumerate}
\exrefs{\S\ref{sec:convexity}}
\end{ex}

target_text:
\begin{ex}{Kombinasi Konveks dan Geometri}{}
\label{ex:convex-combo-triangle}
\stars{2}Misalkan \( P \) adalah segitiga dengan titik-titik sudut \( (0,0) \), \( (2,0) \), dan \( (0,2) \).
\begin{enumerate}
    \item Gambarkan himpunan \( P \).
    \item Tentukan apakah titik \( (1,1) \) merupakan kombinasi konveks titik-titik sudut tersebut.
    \item Tentukan apakah titik \( (1.5,1.5) \) berada dalam \( P \).
\end{enumerate}
\exrefs{\S\ref{sec:convexity}}
\end{ex}

source_text:
\begin{ex}{Halfspace Geometry and Convexity}{}
\stars{2}Consider the halfspace \( H = \{ \mathbf{x} \in \mathbb{R}^2 : x_1 + 2x_2 \leq 4 \} \).
\begin{enumerate}
    \item Plot the halfspace and the boundary.
    \item Is the point \( (2,1) \) in \( H \)? What about \( (1,2) \)?
    \item Verify that the set is convex by checking whether the midpoint between \( (0,0) \) and \( (2,1) \) lies in \( H \).
\end{enumerate}
\exrefs{\S\ref{sec:convexity}, Theorem~\ref{thm:polyhedra_convex}}
\end{ex}

target_text:
\begin{ex}{Geometri dan Konveksitas Setengah Ruang}{}
\stars{2}Perhatikan setengah ruang \( H = \{ \mathbf{x} \in \mathbb{R}^2 : x_1 + 2x_2 \leq 4 \} \).
\begin{enumerate}
    \item Gambarkan setengah ruang dan batasnya.
    \item Apakah titik \( (2,1) \) berada dalam \( H \)? Bagaimana dengan \( (1,2) \)?
    \item Verifikasi bahwa himpunan tersebut konveks dengan memeriksa apakah titik tengah antara \( (0,0) \) dan \( (2,1) \) berada dalam \( H \).
\end{enumerate}
\exrefs{\S\ref{sec:convexity}, Teorema~\ref{thm:polyhedra_convex}}
\end{ex}

source_text:
\begin{ex}{Checking an Extreme Point}{}
\label{ex:extreme-point-check}
\stars{2}Let
\[
P = \{ \mathbf{x} \in \mathbb{R}^2 : x_1 - 4x_2 \leq 0,\ -x_1 + x_2 \leq 1,\ -x_1 + 2x_2 \leq 4,\ x_1 \geq 0,\ x_2 \geq 0 \}
\]
be the feasible region used to illustrate the Representation Theorem.
\begin{enumerate}
    \item Verify that \( (2,3) \in P \), identify the constraints that are tight there, and show that the tight rows are linearly independent. Conclude that \( (2,3) \) is a vertex of \( P \), and hence an extreme point.
    \item Verify that \( (1,2) \in P \) and show that only one constraint is tight there. Then express \( (1,2) \) as a convex combination of two other points of \( P \) to conclude that \( (1,2) \) is not an extreme point.
\end{enumerate}
\exrefs{\S\ref{sec:algebraic-vertex-proof}, \S\ref{sec:convexity}}
\end{ex}

target_text:
\begin{ex}{Memeriksa Titik Ekstrem}{}
\label{ex:extreme-point-check}
\stars{2}Misalkan
\[
P = \{ \mathbf{x} \in \mathbb{R}^2 : x_1 - 4x_2 \leq 0,\ -x_1 + x_2 \leq 1,\ -x_1 + 2x_2 \leq 4,\ x_1 \geq 0,\ x_2 \geq 0 \}
\]
adalah daerah layak yang digunakan untuk menggambarkan Teorema Representasi.
\begin{enumerate}
    \item Verifikasi bahwa \( (2,3) \in P \), tentukan kendala yang aktif di sana, dan tunjukkan bahwa baris-baris aktif bebas linier. Simpulkan bahwa \( (2,3) \) merupakan titik sudut \( P \), dan karena itu merupakan titik ekstrem.
    \item Verifikasi bahwa \( (1,2) \in P \) dan tunjukkan bahwa hanya satu kendala yang aktif di sana. Kemudian nyatakan \( (1,2) \) sebagai kombinasi konveks dari dua titik lain dalam \( P \) untuk menyimpulkan bahwa \( (1,2) \) bukan titik ekstrem.
\end{enumerate}
\exrefs{\S\ref{sec:algebraic-vertex-proof}, \S\ref{sec:convexity}}
\end{ex}

source_text:
\begin{ex}{A Convex Combination of Extreme Points}{}
\label{ex:rep-theorem-combo}
\stars{2}The polyhedron \( P \) from Exercise~\ref{ex:extreme-point-check} has extreme points \( (0,0) \), \( (0,1) \), and \( (2,3) \). Following the illustration of the Representation Theorem, find multipliers \( \lambda_1, \lambda_2, \lambda_3 \geq 0 \) with \( \lambda_1 + \lambda_2 + \lambda_3 = 1 \) such that
\[
\lambda_1 \begin{bmatrix} 0 \\ 0 \end{bmatrix} + \lambda_2 \begin{bmatrix} 0 \\ 1 \end{bmatrix} + \lambda_3 \begin{bmatrix} 2 \\ 3 \end{bmatrix} = \begin{bmatrix} 1 \\ 7/4 \end{bmatrix}.
\]
Why are no extreme directions needed to represent this point?
\exrefs{\S\ref{sec:convexity}, Theorem~\ref{thm:representation}}
\end{ex}

target_text:
\begin{ex}{Kombinasi Konveks Titik-Titik Ekstrem}{}
\label{ex:rep-theorem-combo}
\stars{2}Polihedron \( P \) dari Latihan~\ref{ex:extreme-point-check} memiliki titik-titik ekstrem \( (0,0) \), \( (0,1) \), dan \( (2,3) \). Dengan mengikuti ilustrasi Teorema Representasi, temukan pengali \( \lambda_1, \lambda_2, \lambda_3 \geq 0 \) dengan \( \lambda_1 + \lambda_2 + \lambda_3 = 1 \) sedemikian sehingga
\[
\lambda_1 \begin{bmatrix} 0 \\ 0 \end{bmatrix} + \lambda_2 \begin{bmatrix} 0 \\ 1 \end{bmatrix} + \lambda_3 \begin{bmatrix} 2 \\ 3 \end{bmatrix} = \begin{bmatrix} 1 \\ 7/4 \end{bmatrix}.
\]
Mengapa arah ekstrem tidak diperlukan untuk menyatakan titik ini?
\exrefs{\S\ref{sec:convexity}, Teorema~\ref{thm:representation}}
\end{ex}

source_text:
\begin{ex}{Is the Union of Convex Sets Convex?}{}
\label{ex:union-convex}
\stars{2}The chapter shows that the intersection of two convex sets is always convex.
\begin{enumerate}
    \item Give an example of two convex sets \( C_1, C_2 \subseteq \mathbb{R}^2 \) whose union \( C_1 \cup C_2 \) is not convex, and verify your claim by exhibiting two points of the union whose midpoint is not in the union.
    \item Find a condition on \( C_1 \) and \( C_2 \) under which the union is convex, and justify it.
\end{enumerate}
\exrefs{\S\ref{sec:convexity}}
\end{ex}

target_text:
\begin{ex}{Apakah Gabungan Himpunan Konveks Bersifat Konveks?}{}
\label{ex:union-convex}
\stars{2}Bab ini menunjukkan bahwa irisan dua himpunan konveks selalu bersifat konveks.
\begin{enumerate}
    \item Berikan contoh dua himpunan konveks \( C_1, C_2 \subseteq \mathbb{R}^2 \) yang gabungannya \( C_1 \cup C_2 \) tidak konveks, lalu verifikasi pernyataan Anda dengan memberikan dua titik dalam gabungan yang titik tengahnya tidak berada dalam gabungan.
    \item Temukan suatu syarat pada \( C_1 \) dan \( C_2 \) yang membuat gabungannya konveks, lalu berikan alasannya.
\end{enumerate}
\exrefs{\S\ref{sec:convexity}}
\end{ex}

source_text:
\begin{ex}{Where Boundedness Enters the Vertex Theorem}{}
\label{ex:boundedness-vertex}
\stars{2}The proof in \S\ref{sec:algebraic-vertex-proof} that some optimal solution lies at a vertex assumes the feasible region \( P \) is bounded.
\begin{enumerate}
    \item Point to the exact step of the proof where boundedness is used, and explain what could go wrong without it.
    \item Let \( P = \{ \mathbf{x} \in \mathbb{R}^2 : 0 \leq x_2 \leq 1 \} \) and consider maximizing \( -x_2 \) over \( P \). Show that \( P \) has no vertex at all, that the LP nevertheless has optimal solutions, and describe the set of optima. Which hypothesis of the theorem fails, and why does this example not contradict the theorem?
\end{enumerate}
\exrefs{\S\ref{sec:algebraic-vertex-proof}}
\end{ex}

target_text:
\begin{ex}{Letak Penggunaan Keterbatasan dalam Teorema Titik Sudut}{}
\label{ex:boundedness-vertex}
\stars{2}Bukti dalam \S\ref{sec:algebraic-vertex-proof} bahwa suatu solusi optimal terletak pada titik sudut mengasumsikan daerah layak \( P \) terbatas.
\begin{enumerate}
    \item Tunjukkan langkah persis dalam bukti yang menggunakan keterbatasan dan jelaskan apa yang dapat gagal tanpanya.
    \item Misalkan \( P = \{ \mathbf{x} \in \mathbb{R}^2 : 0 \leq x_2 \leq 1 \} \) dan perhatikan masalah memaksimumkan \( -x_2 \) atas \( P \). Tunjukkan bahwa \( P \) sama sekali tidak memiliki titik sudut, tetapi program linier tersebut tetap memiliki solusi optimal, lalu jelaskan himpunan optimumnya. Hipotesis teorema mana yang gagal, dan mengapa contoh ini tidak bertentangan dengan teorema?
\end{enumerate}
\exrefs{\S\ref{sec:algebraic-vertex-proof}}
\end{ex}

source_text:
\begin{ex}{Intersections of Arbitrary Families of Convex Sets}{}
\label{ex:intersection-family}
\stars{3}Let \( \{ C_i \}_{i \in I} \) be any family of convex sets in \( \mathbb{R}^n \), where the index set \( I \) may be infinite. Prove that the intersection
\[
C = \bigcap_{i \in I} C_i
\]
is convex. Explain why this result, applied to halfspaces, gives another proof of Theorem~\ref{thm:polyhedra_convex}. (Note that \( C \) may be empty; the empty set is convex vacuously.)
\exrefs{\S\ref{sec:convexity}, Theorem~\ref{thm:polyhedra_convex}}
\end{ex}

target_text:
\begin{ex}{Irisan Keluarga Himpunan Konveks Sembarang}{}
\label{ex:intersection-family}
\stars{3}Misalkan \( \{ C_i \}_{i \in I} \) adalah sembarang keluarga himpunan konveks dalam \( \mathbb{R}^n \), dengan himpunan indeks \( I \) yang mungkin tak berhingga. Buktikan bahwa irisan
\[
C = \bigcap_{i \in I} C_i
\]
bersifat konveks. Jelaskan mengapa hasil ini, ketika diterapkan pada setengah ruang, memberikan bukti lain bagi Teorema~\ref{thm:polyhedra_convex}. (Perhatikan bahwa \( C \) mungkin kosong; himpunan kosong bersifat konveks secara vakum.)
\exrefs{\S\ref{sec:convexity}, Teorema~\ref{thm:polyhedra_convex}}
\end{ex}

source_text:
\begin{solution}(Exercise~\ref{ex:vector-operations})
Working componentwise:
\begin{enumerate}
    \item \( \mathbf{v} + \mathbf{u} = [3 + (-1),\ -2 + 0,\ 4 + 2] = [2, -2, 6] \).
    \item \( 2\mathbf{v} = [6, -4, 8] \).
    \item \( \mathbf{v} \cdot \mathbf{u} = (3)(-1) + (-2)(0) + (4)(2) = -3 + 0 + 8 = 5 \).
\end{enumerate}
\end{solution}

target_text:
\begin{solution}(Latihan~\ref{ex:vector-operations})
Dengan menghitung per komponen:
\begin{enumerate}
    \item \( \mathbf{v} + \mathbf{u} = [3 + (-1),\ -2 + 0,\ 4 + 2] = [2, -2, 6] \).
    \item \( 2\mathbf{v} = [6, -4, 8] \).
    \item \( \mathbf{v} \cdot \mathbf{u} = (3)(-1) + (-2)(0) + (4)(2) = -3 + 0 + 8 = 5 \).
\end{enumerate}
\end{solution}

source_text:
\begin{enumerate}
    \item The plot is the triangle with the three given vertices.
    \item Yes.  Take \( \lambda_1 = 0 \), \( \lambda_2 = \lambda_3 = \tfrac12 \):
    \[
    0 \begin{bmatrix} 0 \\ 0 \end{bmatrix} + \tfrac12 \begin{bmatrix} 2 \\ 0 \end{bmatrix} + \tfrac12 \begin{bmatrix} 0 \\ 2 \end{bmatrix} = \begin{bmatrix} 1 \\ 1 \end{bmatrix},
    \]
    and the weights are nonnegative and sum to \( 1 \).
    \item No.  Any combination of the vertices hitting \( (1.5, 1.5) \) must satisfy \( 2\lambda_2 = 1.5 \) and \( 2\lambda_3 = 1.5 \), forcing \( \lambda_2 = \lambda_3 = 0.75 \) and \( \lambda_2 + \lambda_3 = 1.5 > 1 \).  Equivalently, \( 1.5 + 1.5 = 3 > 2 \) violates \( x_1 + x_2 \leq 2 \), so \( (1.5, 1.5) \notin P \).
\end{enumerate}
\end{solution}

target_text:
\begin{enumerate}
    \item Gambarnya adalah segitiga dengan ketiga titik sudut yang diberikan.
    \item Ya. Ambil \( \lambda_1 = 0 \), \( \lambda_2 = \lambda_3 = \tfrac12 \):
    \[
    0 \begin{bmatrix} 0 \\ 0 \end{bmatrix} + \tfrac12 \begin{bmatrix} 2 \\ 0 \end{bmatrix} + \tfrac12 \begin{bmatrix} 0 \\ 2 \end{bmatrix} = \begin{bmatrix} 1 \\ 1 \end{bmatrix},
    \]
    dan bobot-bobotnya tak negatif serta berjumlah \( 1 \).
    \item Tidak. Setiap kombinasi titik-titik sudut yang mencapai \( (1.5, 1.5) \) harus memenuhi \( 2\lambda_2 = 1.5 \) dan \( 2\lambda_3 = 1.5 \), yang memaksakan \( \lambda_2 = \lambda_3 = 0.75 \) serta \( \lambda_2 + \lambda_3 = 1.5 > 1 \). Secara ekuivalen, \( 1.5 + 1.5 = 3 > 2 \) melanggar \( x_1 + x_2 \leq 2 \), sehingga \( (1.5, 1.5) \notin P \).
\end{enumerate}
\end{solution}

source_text:
\begin{solution}(Exercise~\ref{ex:union-convex})
\begin{enumerate}
    \item Take \( C_1 \) to be the unit disk centered at \( (-2,0) \) and \( C_2 \) the unit disk centered at \( (2,0) \). Each disk is convex. The points \( (-2,0) \in C_1 \) and \( (2,0) \in C_2 \) both lie in the union, but their midpoint \( (0,0) \) is at distance \( 2 > 1 \) from both centers, so it lies in neither disk. Hence \( C_1 \cup C_2 \) is not convex.
    \item If one set contains the other, say \( C_1 \subseteq C_2 \), then \( C_1 \cup C_2 = C_2 \), which is convex. Nesting is sufficient but not necessary: with \( C_1 = \{ \mathbf{x} : x_2 \geq 0 \} \) and \( C_2 = \{ \mathbf{x} : x_2 \leq 0 \} \), neither halfplane contains the other, yet \( C_1 \cup C_2 = \mathbb{R}^2 \) is convex.
\end{enumerate}
\end{solution}

target_text:
\begin{solution}(Latihan~\ref{ex:union-convex})
\begin{enumerate}
    \item Ambil \( C_1 \) sebagai cakram satuan yang berpusat di \( (-2,0) \) dan \( C_2 \) sebagai cakram satuan yang berpusat di \( (2,0) \). Setiap cakram bersifat konveks. Titik \( (-2,0) \in C_1 \) dan \( (2,0) \in C_2 \) sama-sama berada dalam gabungan, tetapi titik tengahnya \( (0,0) \) berjarak \( 2 > 1 \) dari kedua pusat, sehingga tidak berada dalam cakram mana pun. Jadi, \( C_1 \cup C_2 \) tidak konveks.
    \item Jika salah satu himpunan memuat himpunan lainnya, misalnya \( C_1 \subseteq C_2 \), maka \( C_1 \cup C_2 = C_2 \), yang bersifat konveks. Keterangkuman merupakan syarat cukup, tetapi bukan syarat perlu: dengan \( C_1 = \{ \mathbf{x} : x_2 \geq 0 \} \) dan \( C_2 = \{ \mathbf{x} : x_2 \leq 0 \} \), kedua setengah bidang tidak saling memuat, tetapi \( C_1 \cup C_2 = \mathbb{R}^2 \) bersifat konveks.
\end{enumerate}
\end{solution}

source_text:
% Copyright 2025 by Robert Hildebrand
%This work is licensed under a
%Creative Commons Attribution-ShareAlike 4.0 International License (CC BY-SA 4.0)
%See http://creativecommons.org/licenses/by-sa/4.0/
\chapter{Simplex Method}
\label{ch:simplex-dictionary}
\begin{outcome}
\begin{itemize}
\item Convert linear programs to standard form
\item Reformulate linear programs from the perspective of different bases
\item Define \emph{basic solutions} and \emph{basic feasible solutions}
\item Describe optimality condition from the perspective of a reformulation
\item Develop the \emph{Simplex Method} that \emph{pivots} through basic feasible solutions
\end{itemize}
\end{outcome}

target_text:
% Hak cipta 2025 oleh Robert Hildebrand
%Karya ini dilisensikan berdasarkan
%Lisensi Internasional Creative Commons Atribusi-BerbagiSerupa 4.0 (CC BY-SA 4.0)
%Lihat http://creativecommons.org/licenses/by-sa/4.0/
\chapter{Metode Simpleks}
\label{ch:simplex-dictionary}
\begin{outcome}
\begin{itemize}
\item Mengonversi program linier ke bentuk standar
\item Merumuskan ulang program linier dari sudut pandang basis yang berbeda
\item Mendefinisikan \emph{solusi basis} dan \emph{solusi basis layak}
\item Menjelaskan kondisi optimalitas dari sudut pandang suatu perumusan ulang
\item Mengembangkan \emph{Metode Simpleks} yang melakukan \emph{pivot} melalui solusi-solusi basis layak
\end{itemize}
\end{outcome}

source_text:
\begin{quote}
\itshape Picture hiking to the highest point of a fenced field on a moonless night. Your flashlight shows only the ground at your feet: the corner you are standing on and the fence lines leading away from it. A sensible strategy suggests itself: shine the light along each fence line; if one leads uphill, follow it to the next corner and look again; if none does, stop. The remarkable fact of this chapter is that for linear programs this nearsighted strategy is guaranteed to end at the highest point of the entire field. The algebra of ``shining the flashlight'' is a reformulation of the linear program called a \emph{dictionary}.
\end{quote}

target_text:
\begin{quote}
\itshape Bayangkan Anda mendaki menuju titik tertinggi sebuah lapangan berpagar pada malam tanpa bulan. Senter Anda hanya menerangi tanah di kaki Anda: sudut tempat Anda berdiri dan garis-garis pagar yang menjauh darinya. Sebuah strategi yang masuk akal pun muncul: arahkan cahaya sepanjang setiap garis pagar; jika salah satunya menanjak, ikuti hingga sudut berikutnya lalu periksa lagi; jika tidak ada yang menanjak, berhentilah. Fakta luar biasa dalam bab ini adalah bahwa untuk program linier, strategi berpandangan dekat ini dijamin berakhir di titik tertinggi seluruh lapangan. Aljabar dari ``mengarahkan senter'' merupakan suatu perumusan ulang program linier yang disebut \emph{kamus}.
\end{quote}

source_text:
A linear program is in \emph{standard form} if it satisfies all of the following:
\begin{itemize}
    \item The objective is a maximization.
    \item All constraints are equalities (i.e., of the form \( = \)).
    \item All variables are bounded below by zero (i.e., \( x_i \geq 0 \)).
\end{itemize}

target_text:
Suatu program linier berada dalam \emph{bentuk standar} jika memenuhi semua hal berikut:
\begin{itemize}
    \item Fungsi objektifnya berupa maksimisasi.
    \item Semua kendala berupa persamaan (yaitu, berbentuk \( = \)).
    \item Semua variabel dibatasi dari bawah oleh nol (yaitu, \( x_i \geq 0 \)).
\end{itemize}

source_text:
\begin{definition}{Standard Form}\label{def:standardform}
A linear program is in \emph{standard form} if it is written as
\begin{align*}
\max \ \ &\c^\top \x \\
s.t. \ \ & A\x = \b\\
& \x \geq 0.
\end{align*}
\end{definition}

target_text:
\begin{definition}{Bentuk Standar}\label{def:standardform}
Suatu program linier berada dalam \emph{bentuk standar} jika ditulis sebagai
\begin{align*}
\max \ \ &\c^\top \x \\
s.t. \ \ & A\x = \b\\
& \x \geq 0.
\end{align*}
\end{definition}

source_text:
\begin{example}{Unrestricted Variable to Two Variables}
    Suppose \( x_4 \) is unrestricted. We define:
    \[
    x_4 = x_4^+ - x_4^-, \quad \text{with } x_4^+, x_4^- \geq 0.
    \]
    Here, \( x_4^+ \) captures the positive part and \( x_4^- \) captures the negative part. At most one of them will be nonzero in a basic feasible solution.
    \end{example}
\end{itemize}

target_text:
\begin{example}{Variabel Bebas Menjadi Dua Variabel}
    Misalkan \( x_4 \) bebas. Kita mendefinisikan:
    \[
x_4 = x_4^+ - x_4^-, \quad \text{dengan } x_4^+, x_4^- \geq 0.
    \]
    Di sini, \( x_4^+ \) menangkap bagian positif dan \( x_4^- \) menangkap bagian negatif. Paling banyak salah satunya akan bernilai taknol dalam suatu solusi basis layak.
    \end{example}
\end{itemize}

source_text:
\smallskip
\textbf{New constraints:}
\begin{align*}
(x_1^+ - x_1^-) - x_2 &\leq 4 \quad &\text{(original 1st constraint)} \\
2(x_1^+ - x_1^-) + (x_3^+ - x_3^-) &= 7 \quad &\text{(original 2nd constraint)} \\
x_2 - (x_3^+ - x_3^-) &\geq 2 \quad &\text{(original 3rd constraint)}
\end{align*}

target_text:
\smallskip
\textbf{Kendala baru:}
\begin{align*}
(x_1^+ - x_1^-) - x_2 &\leq 4 \quad &\text{(kendala semula ke-1)} \\
2(x_1^+ - x_1^-) + (x_3^+ - x_3^-) &= 7 \quad &\text{(kendala semula ke-2)} \\
x_2 - (x_3^+ - x_3^-) &\geq 2 \quad &\text{(kendala semula ke-3)}
\end{align*}

source_text:
\begin{remark}{Variable Transformations Preserve Solution Meaning}{}
To convert a linear program into standard form, we often introduce new variables:
\begin{itemize}
    \item Slack variables to convert \( \leq \) constraints to equalities,
    \item Surplus variables for \( \geq \) constraints,
    \item Split unrestricted variables as \( x_j = x_j^+ - x_j^- \),
    \item Negate variables with \( x_j \leq 0 \).
\end{itemize}

target_text:
\begin{remark}{Transformasi Variabel Mempertahankan Makna Solusi}{}
Untuk mengonversi suatu program linier ke bentuk standar, kita sering memperkenalkan variabel baru:
\begin{itemize}
    \item Variabel slack untuk mengonversi kendala \( \leq \) menjadi persamaan,
    \item Variabel surplus untuk kendala \( \geq \),
    \item Memecah variabel bebas sebagai \( x_j = x_j^+ - x_j^- \),
    \item Menegasikan variabel dengan \( x_j \leq 0 \).
\end{itemize}

source_text:
These transformations may change the number of variables and the way solutions are expressed, but:
\begin{enumerate}
    \item Every feasible solution to the transformed problem corresponds to a feasible solution of the original problem.
    \item Every optimal solution of the transformed problem yields an optimal solution to the original.
\end{enumerate}

target_text:
Transformasi ini dapat mengubah jumlah variabel dan cara solusi dinyatakan, tetapi:
\begin{enumerate}
    \item Setiap solusi layak bagi masalah hasil transformasi berkorespondensi dengan suatu solusi layak bagi masalah semula.
    \item Setiap solusi optimal dari masalah hasil transformasi menghasilkan solusi optimal bagi masalah semula.
\end{enumerate}

