source_text:
\begin{proposition}{Existence of Canonical Form for Feasible LPs}\label{prop:canonical-exists}
Let \( P \) be a linear program in standard form:
\[
\begin{aligned}
\max \quad & \mathbf{c}^\top \mathbf{x} \\
\st \quad & A\mathbf{x} = \mathbf{b}, \\
& \mathbf{x} \geq 0.
\end{aligned}
\]
If \( P \) is feasible (i.e., \( \exists \mathbf{x} \geq 0 \) such that \( A\mathbf{x} = \mathbf{b} \)), then there exists an equivalent linear program in \emph{canonical form}, that is, a reformulation where:
\begin{itemize}
    \item \( A \) contains the identity matrix \( I_m \) as a submatrix,
    \item The corresponding basic variables yield a basic feasible solution with \( \mathbf{b} \geq 0 \),
    \item The objective function is unchanged in value on feasible solutions.
\end{itemize}
\end{proposition}

target_text:
\begin{proposition}{Eksistensi Bentuk Kanonik untuk PL Layak}\label{prop:canonical-exists}
Misalkan \( P \) adalah suatu program linier berbentuk standar:
\[
\begin{aligned}
\max \quad & \mathbf{c}^\top \mathbf{x} \\
\st \quad & A\mathbf{x} = \mathbf{b}, \\
& \mathbf{x} \geq 0.
\end{aligned}
\]
Jika \( P \) layak (yaitu, \( \exists \mathbf{x} \geq 0 \) sedemikian sehingga \( A\mathbf{x} = \mathbf{b} \)), maka terdapat program linier ekuivalen dalam \emph{bentuk kanonik}, yaitu suatu perumusan ulang dengan:
\begin{itemize}
    \item \( A \) memuat matriks identitas \( I_m \) sebagai submatriks,
    \item Variabel basis yang bersesuaian menghasilkan solusi basis layak dengan \( \mathbf{b} \geq 0 \),
    \item Nilai fungsi objektif tidak berubah pada solusi-solusi layak.
\end{itemize}
\end{proposition}

