\item \textbf{First Iteration:}
\begin{enumerate}
    \item \textbf{Ratio Test:} \( y \) enters, \( s_3 \) leaves.

target_text:
\item \textbf{Iterasi Pertama:}
\begin{enumerate}
    \item \textbf{Uji Rasio:} \( y \) masuk, \( s_3 \) keluar.

source_text:
\item \textbf{Dictionary after Pivoting \( y \) in, \( s_3 \) out}  
    \begin{tcolorbox}[colback=blue!5!white, colframe=blue!75!black,    
    width=0.6\textwidth, % adjust width as desired
    box align=center, 
    title=\textbf{Second Dictionary}]
    \[
    \begin{aligned}
    \max \quad & z = 21 + \frac{1}{2}x - \frac{3}{2}s_3 \\
    \st \quad 
    & s_1 = 2 - \frac{1}{2}x + \frac{1}{2}s_3, \\
    & s_2 = 9 - \frac{3}{2}x + \frac{1}{2}s_3, \\
    & y = 7 - \frac{1}{2}x - \frac{1}{2}s_3.
    \end{aligned}
    \]
    \end{tcolorbox}
    Basic Feasible Solution: \( (s_1, s_2, y) = (2,9,7), (x,s_3) = (0,0) \)  
    Objective Value: \( z = 21 \).\\ 
    Since the objective row has a positive coefficient, it is not optimal.  
    \end{enumerate}
    \item \textbf{Second Iteration}
    \begin{enumerate}
    \item \textbf{Ratio Test:} \( x \) enters, \( s_1 \) leaves.

target_text:
\item \textbf{Kamus setelah Pivot dengan \( y \) masuk dan \( s_3 \) keluar}  
    \begin{tcolorbox}[colback=blue!5!white, colframe=blue!75!black,    
    width=0.6\textwidth, % sesuaikan lebar sesuai keinginan
    box align=center, 
    title=\textbf{Kamus Kedua}]
    \[
    \begin{aligned}
    \max \quad & z = 21 + \frac{1}{2}x - \frac{3}{2}s_3 \\
    \st \quad 
    & s_1 = 2 - \frac{1}{2}x + \frac{1}{2}s_3, \\
    & s_2 = 9 - \frac{3}{2}x + \frac{1}{2}s_3, \\
    & y = 7 - \frac{1}{2}x - \frac{1}{2}s_3.
    \end{aligned}
    \]
    \end{tcolorbox}
    Solusi Basis Layak: \( (s_1, s_2, y) = (2,9,7), (x,s_3) = (0,0) \)  
    Nilai Fungsi Objektif: \( z = 21 \).\\ 
    Karena baris objektif memiliki koefisien positif, solusi ini belum optimal.  
    \end{enumerate}
    \item \textbf{Iterasi Kedua}
    \begin{enumerate}
    \item \textbf{Uji Rasio:} \( x \) masuk, \( s_1 \) keluar.

source_text:
\item \textbf{Final Dictionary (Optimal) after pivoting $x$ in, $s_1$ out.} 
    \begin{tcolorbox}[colback=green!5!white, colframe=green!75!black,    
    width=0.6\textwidth, % adjust width as desired
    box align=center, 
    title=\textbf{Final Dictionary}] 
    \[
    \begin{aligned}
    \max \quad & z = 23 - s_1 - s_3 \\
    \st \quad
    & x = 4 - 2s_1 + s_3, \\
    & y = 5 + s_1 - s_3, \\
    & s_2 = 3 + 3s_1 - s_3.
    \end{aligned}
    \]
    \end{tcolorbox}
    Basic Feasible Solution: \( (x,y,s_2) = (4,5,3), (s_1,s_3) = (0,0) \)  
    Objective Value: \( z = 23 \).\\ 
    Since all coefficients in the objective row are non-positive, this is the optimal solution.
    \end{enumerate}
\end{enumerate}

target_text:
\item \textbf{Kamus Akhir (Optimal) setelah pivot dengan $x$ masuk dan $s_1$ keluar.} 
    \begin{tcolorbox}[colback=green!5!white, colframe=green!75!black,    
    width=0.6\textwidth, % sesuaikan lebar sesuai keinginan
    box align=center, 
    title=\textbf{Kamus Akhir}] 
    \[
    \begin{aligned}
    \max \quad & z = 23 - s_1 - s_3 \\
    \st \quad
    & x = 4 - 2s_1 + s_3, \\
    & y = 5 + s_1 - s_3, \\
    & s_2 = 3 + 3s_1 - s_3.
    \end{aligned}
    \]
    \end{tcolorbox}
    Solusi Basis Layak: \( (x,y,s_2) = (4,5,3), (s_1,s_3) = (0,0) \)  
    Nilai Fungsi Objektif: \( z = 23 \).\\ 
    Karena semua koefisien pada baris objektif nonpositif, inilah solusi optimal.
    \end{enumerate}
\end{enumerate}

