source_text:
\begin{outcome}
\begin{itemize}
\item Address case where initial basis is infeasible
\item Modify the simplex algorithm using the Big-M method to find a feasible starting basis
\begin{itemize}
\item Introduce artificial variables to rows that violate initial feasibility
\item Add large penalty (Big-M) to the objective on these artificial variables
\item Run Simplex and pivot until can remove artificial variables
\item Drop the auxiliary variables and proceed with the simplex algorithm
\end{itemize}
\end{itemize}
\end{outcome}

target_text:
\begin{outcome}
\begin{itemize}
\item Menangani kasus ketika basis awal tidak layak
\item Memodifikasi algoritma simpleks menggunakan Metode Big-M untuk menemukan basis awal yang layak
\begin{itemize}
\item Memperkenalkan variabel artifisial pada baris yang melanggar kelayakan awal
\item Menambahkan penalti besar (Big-M) pada variabel artifisial dalam fungsi objektif
\item Menjalankan Simpleks dan melakukan pivot hingga variabel artifisial dapat dihilangkan
\item Menghapus variabel bantu dan melanjutkan algoritma simpleks
\end{itemize}
\end{itemize}
\end{outcome}

