source_text:
\begin{ex}{Standard form and the first dictionary}{}
\label{ex:standard-form-warmup-dictionary}
\stars{1} Consider the linear program
\[
\begin{aligned}
\max \quad & 4x + 5y \\
\st \quad
& x + 2y \leq 12, \\
& 3x + 2y \leq 24, \\
& x, y \geq 0.
\end{aligned}
\]
\begin{enumerate}
    \item Convert the program to standard form by introducing slack variables $s_1, s_2$.
    \item Write the initial dictionary for the slack basis $\{s_1, s_2\}$, exactly as in the Initial Dictionary of Section~\ref{sec:pivoting}.
    \item Read off the basic feasible solution and its objective value.
    \item Under the steepest ascent rule, which variable would enter the basis first?
\end{enumerate}
\exrefs{\S\ref{sec:pivoting}, Initial Dictionary; \S\ref{sec:standard-form}}
\end{ex}

target_text:
\begin{ex}{Bentuk standar dan kamus pertama}{}
\label{ex:standard-form-warmup-dictionary}
\stars{1} Perhatikan program linier
\[
\begin{aligned}
\max \quad & 4x + 5y \\
\st \quad
& x + 2y \leq 12, \\
& 3x + 2y \leq 24, \\
& x, y \geq 0.
\end{aligned}
\]
\begin{enumerate}
    \item Konversikan program ke bentuk standar dengan memperkenalkan variabel slack $s_1, s_2$.
    \item Tuliskan kamus awal untuk basis slack $\{s_1, s_2\}$, tepat seperti dalam Kamus Awal pada Bagian~\ref{sec:pivoting}.
    \item Baca solusi basis layak dan nilai fungsi objektifnya.
    \item Berdasarkan aturan pendakian tercuram, variabel mana yang akan masuk ke basis terlebih dahulu?
\end{enumerate}
\exrefs{\S\ref{sec:pivoting}, Kamus Awal; \S\ref{sec:standard-form}}
\end{ex}

