\begin{ex}{Simplex Method Practice}{}
\label{ex:simplex-practice-5-3}
\stars{2} Solve the following linear programming problem using the simplex method:
\[
\begin{aligned}
\text{Maximize:}\quad & z = 5x_{1} + 3x_{2}\\
\text{subject to:}\quad & x_{1} + x_{2} \le 12,\\
& 2x_{1} + x_{2} \le 16,\\
& x_{1},\, x_{2} \ge 0.
\end{aligned}
\]
\exrefs{\S\ref{sec:pivoting}; \S\ref{sec:simplex-algorithm}}
\end{ex}

