\begin{ex}{Dictionary Optimality}{}
\label{ex:dictionary-optimality-conditions}
\stars{2} {Conditions in the dictionary.} The following is a dictionary of a maximization problem. State conditions (i.e., the range of values) on $a_{1}, a_{2}, b, c_{1}, c_{5}, c_{6}$ that are required to make the following true.  Note: This does not require any simplex pivots.
\begin{center}
\begin{align*}
\max \quad &0 + c_1 x_1 + c_5 x_5 + c_6 x_6 \\
x_2 &= 1 + x_1 - a_1 x_5 \\
x_4 &= 2 + x_1 + 2x_5 - x_6 \\
x_3 &= b - a_2 x_1 - x_5 - x_6
\end{align*}
\end{center}

target_text:
\begin{ex}{Optimalitas Kamus}{}
\label{ex:dictionary-optimality-conditions}
\stars{2} {Kondisi dalam kamus.} Berikut adalah kamus suatu masalah maksimisasi. Nyatakan kondisi (yaitu, rentang nilai) pada $a_{1}, a_{2}, b, c_{1}, c_{5}, c_{6}$ yang diperlukan agar hal-hal berikut berlaku. Catatan: Ini tidak memerlukan pivot simpleks apa pun.
\begin{center}
\begin{align*}
\max \quad &0 + c_1 x_1 + c_5 x_5 + c_6 x_6 \\
x_2 &= 1 + x_1 - a_1 x_5 \\
x_4 &= 2 + x_1 + 2x_5 - x_6 \\
x_3 &= b - a_2 x_1 - x_5 - x_6
\end{align*}
\end{center}

source_text:
\begin{enumerate}
\item  The current solution is feasible and optimal.
\item The current basic solution is not feasible.
\item  The current basic solution is degenerate.
\item  The current basic solution is feasible, and the LP is unbounded.
\end{enumerate}
\exrefs{\S\ref{sec:simplex-algorithm}; \S\ref{sec:degeneracy}}
\end{ex}

target_text:
\begin{enumerate}
\item Solusi saat ini layak dan optimal.
\item Solusi basis saat ini tidak layak.
\item Solusi basis saat ini degenerat.
\item Solusi basis saat ini layak, dan PL tak terbatas.
\end{enumerate}
\exrefs{\S\ref{sec:simplex-algorithm}; \S\ref{sec:degeneracy}}
\end{ex}

