source_text:
\begin{ex}{What the ratio test protects}{}
\label{ex:ratio-test-wrong-row}
\stars{2} In the second dictionary of the running example of Section~\ref{sec:pivoting},
\[
\begin{aligned}
\max\quad & z = 21 + \tfrac12 x - \tfrac32 s_3 \\
\st\quad & s_1 = 2 - \tfrac12 x + \tfrac12 s_3, \\
& s_2 = 9 - \tfrac32 x + \tfrac12 s_3, \\
& y = 7 - \tfrac12 x - \tfrac12 s_3, \\
& x, y, s_1, s_2, s_3 \geq 0,
\end{aligned}
\]
the entering variable is $x$, and the ratio test selects $s_1$ (ratio $4$) to leave.
\begin{enumerate}
    \item Suppose you ignore the ratio test and instead pivot on the $s_2$ row (ratio $6$), so that $s_2$ leaves.  Compute the resulting basic solution and show that it is infeasible by finding the basic variable that becomes negative.
    \item Explain in general terms what goes wrong when a row other than the minimum-ratio row is chosen: which variables does the minimum ratio protect, and why does overshooting it break feasibility?
\end{enumerate}
\exrefs{\S\ref{sec:simplex-algorithm}, Learning Checkpoint~\ref{lc:ratio-test}}
\end{ex}

target_text:
\begin{ex}{Apa yang dilindungi oleh uji rasio}{}
\label{ex:ratio-test-wrong-row}
\stars{2} Dalam kamus kedua pada contoh berjalan di Bagian~\ref{sec:pivoting},
\[
\begin{aligned}
\max\quad & z = 21 + \tfrac12 x - \tfrac32 s_3 \\
\st\quad & s_1 = 2 - \tfrac12 x + \tfrac12 s_3, \\
& s_2 = 9 - \tfrac32 x + \tfrac12 s_3, \\
& y = 7 - \tfrac12 x - \tfrac12 s_3, \\
& x, y, s_1, s_2, s_3 \geq 0,
\end{aligned}
\]
variabel masuk adalah $x$, dan uji rasio memilih $s_1$ (rasio $4$) untuk keluar.
\begin{enumerate}
    \item Andaikan Anda mengabaikan uji rasio dan justru melakukan pivot pada baris $s_2$ (rasio $6$), sehingga $s_2$ keluar. Hitung solusi basis yang dihasilkan dan tunjukkan bahwa solusi tersebut tidak layak dengan menemukan variabel basis yang menjadi negatif.
    \item Jelaskan secara umum apa yang salah ketika baris selain baris berasio minimum dipilih: variabel mana yang dilindungi oleh rasio minimum, dan mengapa melampauinya merusak kelayakan?
\end{enumerate}
\exrefs{\S\ref{sec:simplex-algorithm}, Pos Pemeriksaan Pembelajaran~\ref{lc:ratio-test}}
\end{ex}

source_text:
\begin{ex}{A tie in the ratio test forces degeneracy}{}
\label{ex:degenerate-tie}
\stars{3} Consider the linear program
\[
\begin{aligned}
\max\quad & 2x + y \\
\st\quad & x + y \leq 4, \\
& 2x + y \leq 8, \\
& x, y \geq 0.
\end{aligned}
\]
\begin{enumerate}
    \item Write the initial dictionary for the slack basis and let $x$ enter.  Show that the ratio test produces a \emph{tie}: both $s_1$ and $s_2$ reach zero at $x = 4$.
    \item Pivot with $s_1$ leaving and write the next dictionary.  Show that it is \emph{degenerate}: a basic variable sits at value zero.
    \item Repeat the pivot with $s_2$ leaving instead, and show that the resulting dictionary is also degenerate.  What do you notice about the reduced cost of $y$ in this dictionary, and what does it suggest about the set of optimal solutions?
    \item Explain why this is a general phenomenon: whenever the minimum ratio is attained by two rows, the dictionary after the pivot must be degenerate.  Then construct your own linear program, different from the one above, whose first pivot has a tied ratio test.
\end{enumerate}
\exrefs{\S\ref{sec:degeneracy}; \S\ref{sec:simplex-algorithm}}
\end{ex}

target_text:
\begin{ex}{Hasil imbang dalam uji rasio memaksa degenerasi}{}
\label{ex:degenerate-tie}
\stars{3} Perhatikan program linier
\[
\begin{aligned}
\max\quad & 2x + y \\
\st\quad & x + y \leq 4, \\
& 2x + y \leq 8, \\
& x, y \geq 0.
\end{aligned}
\]
\begin{enumerate}
    \item Tuliskan kamus awal untuk basis slack dan biarkan $x$ masuk. Tunjukkan bahwa uji rasio menghasilkan \emph{hasil imbang}: baik $s_1$ maupun $s_2$ mencapai nol pada $x = 4$.
    \item Lakukan pivot dengan $s_1$ keluar dan tuliskan kamus berikutnya. Tunjukkan bahwa kamus tersebut \emph{degenerat}: suatu variabel basis bernilai nol.
    \item Ulangi pivot dengan $s_2$ keluar sebagai gantinya, dan tunjukkan bahwa kamus yang dihasilkan juga degenerat. Apa yang Anda perhatikan tentang biaya tereduksi $y$ dalam kamus ini, dan apa yang disiratkannya tentang himpunan solusi optimal?
    \item Jelaskan mengapa ini merupakan fenomena umum: setiap kali rasio minimum dicapai oleh dua baris, kamus setelah pivot pasti degenerat. Kemudian buat program linier Anda sendiri, yang berbeda dari program di atas, yang pivot pertamanya memiliki uji rasio dengan hasil imbang.
\end{enumerate}
\exrefs{\S\ref{sec:degeneracy}; \S\ref{sec:simplex-algorithm}}
\end{ex}

