source_text:
\section{Optimality Conditions}
\label{sec:optimality-conditions}
\begin{outcome}
\begin{itemize}
\item Define reduced costs at a basic feasible solution
\item Establish optimality conditions via the reduced costs
\end{itemize}
\end{outcome}
The objective function of the linear program is given by:
    \[
    z = \c^\top \x.
    \]
    Substituting the partitioned variables \( \x_B \) and \( \x_N \),
    \[
    z =\c_B^\top \x_B +\c_N^\top \x_N.
    \]
    Expressing \( \x_B \) in terms of \( \x_N \), using the basic solution \( \x_B = A_B^{-1}\b- A_B^{-1} A_N \x_N \), we rewrite the objective function as:
    \begin{equation}
    z =\c_B^\top (A_B^{-1}\b- A_B^{-1} A_N \x_N) +\c_N^\top \x_N.
    \end{equation}
    Expanding and regrouping terms:
    \begin{equation}
    z =\c_B^\top A_B^{-1}\b+  (\c_N^\top -\c_B^\top A_B^{-1} A_N )\x_N.
    \end{equation}
    \begin{definition}{Reduced Costs}{}
    The term \(\c_N^\top -\c_B^\top A_B^{-1} A_N \) represents the \emph{reduced costs}.

target_text:
\section{Syarat Optimalitas}
\label{sec:optimality-conditions}
\begin{outcome}
\begin{itemize}
\item Mendefinisikan biaya tereduksi pada suatu solusi basis layak
\item Menetapkan syarat optimalitas melalui biaya tereduksi
\end{itemize}
\end{outcome}
Fungsi objektif program linear diberikan oleh:
    \[
    z = \c^\top \x.
    \]
    Dengan menyubstitusikan variabel yang telah dipartisi, yaitu \( \x_B \) dan \( \x_N \),
    \[
    z =\c_B^\top \x_B +\c_N^\top \x_N.
    \]
    Dengan menyatakan \( \x_B \) dalam \( \x_N \) menggunakan solusi basis \( \x_B = A_B^{-1}\b- A_B^{-1} A_N \x_N \), kita menuliskan ulang fungsi objektif sebagai:
    \begin{equation}
    z =\c_B^\top (A_B^{-1}\b- A_B^{-1} A_N \x_N) +\c_N^\top \x_N.
    \end{equation}
    Dengan menguraikan dan mengelompokkan kembali suku-sukunya:
    \begin{equation}
    z =\c_B^\top A_B^{-1}\b+  (\c_N^\top -\c_B^\top A_B^{-1} A_N )\x_N.
    \end{equation}
    \begin{definition}{Biaya Tereduksi}{}
    Suku \(\c_N^\top -\c_B^\top A_B^{-1} A_N \) merepresentasikan \emph{biaya tereduksi}.

source_text:
\begin{definition}{Revised Simplex Dictionary at basis $B$}{}
The \emph{revised simplex dictionary} at a basis $B$ is 
\begin{equation}
\label{eq:dictionary-general}
\begin{aligned}
\max \quad & \mathbf{c}_B^\top A_B^{-1}\mathbf{b} + (\mathbf{c}_N^\top -  \mathbf{c}_B^\top A_B^{-1}A_N)\mathbf{x}_N\\
\st \quad & 
 \mathbf{x}_B 
\;=\;
A_B^{-1}\,\mathbf{b}
\;-\;
A_B^{-1} \,A_N\,\mathbf{x}_N.\\
& \mathbf{x} \geq 0
\end{aligned}
\end{equation}
\end{definition}

target_text:
