\st \quad & 
 \mathbf{x}_B 
\;=\;
A_B^{-1}\,\mathbf{b}
\;-\;
A_B^{-1} \,A_N\,\mathbf{x}_N.\\
& \mathbf{x} \geq 0
\end{aligned}
\end{equation}
\end{definition}

