\end{bmatrix}
=
\begin{bmatrix}
    -\tfrac{19}{7} & \tfrac17
\end{bmatrix}.
\]

source_text:
\end{steppanel}
\begin{steppanel}{algslate}\cstep{2}{Compute \( A_B^{-1} \)}
\[
A_B^{-1} =
\frac{1}{(2)(1) - (0)(3)}
\begin{bmatrix}
    1 & 0 \\
    -3 & 2
\end{bmatrix}
=
\begin{bmatrix}
    \tfrac12 & 0 \\
    -\tfrac32 & 1
\end{bmatrix}.
\]
As a check, $A_B^{-1}\b = \left(\tfrac{16}{2},\, -\tfrac{3}{2}(16) + 45\right) = (8, 21)$, matching $(x_2, s_2) = (8, 21) \geq 0$: a basic feasible solution.

target_text:
\end{steppanel}
\begin{steppanel}{algslate}\cstep{2}{Hitung \( A_B^{-1} \)}
\[
A_B^{-1} =
\frac{1}{(2)(1) - (0)(3)}
\begin{bmatrix}
    1 & 0 \\
    -3 & 2
\end{bmatrix}
=
\begin{bmatrix}
    \tfrac12 & 0 \\
    -\tfrac32 & 1
\end{bmatrix}.
\]
Sebagai pemeriksaan, $A_B^{-1}\b = \left(\tfrac{16}{2},\, -\tfrac{3}{2}(16) + 45\right) = (8, 21)$, yang sesuai dengan $(x_2, s_2) = (8, 21) \geq 0$: suatu solusi basis layak.

source_text:
\end{steppanel}
\begin{steppanel}{algslate}\cstep{3}{Compute Reduced Costs}
\[
A_B^{-1} A_N =
\begin{bmatrix}
    \tfrac12 & 0 \\
    -\tfrac32 & 1
\end{bmatrix}
\begin{bmatrix}
    1 & 1 \\
    5 & 0
\end{bmatrix}
=
\begin{bmatrix}
    \tfrac12 & \tfrac12 \\
    \tfrac72 & -\tfrac32
\end{bmatrix}.
\]

target_text:
\end{steppanel}
\begin{steppanel}{algslate}\cstep{3}{Hitung Biaya Tereduksi}
\[
A_B^{-1} A_N =
\begin{bmatrix}
    \tfrac12 & 0 \\
    -\tfrac32 & 1
\end{bmatrix}
\begin{bmatrix}
    1 & 1 \\
    5 & 0
\end{bmatrix}
=
\begin{bmatrix}
    \tfrac12 & \tfrac12 \\
    \tfrac72 & -\tfrac32
\end{bmatrix}.
\]

source_text:
\[
\c_N^\top -\c_B^\top A_B^{-1} A_N =
\begin{bmatrix}
    2 & 0
\end{bmatrix}
-
\begin{bmatrix}
    5 & 0
\end{bmatrix}
\begin{bmatrix}
    \tfrac12 & \tfrac12 \\
    \tfrac72 & -\tfrac32
\end{bmatrix}
=
\begin{bmatrix}
    2 & 0
\end{bmatrix}
-
\begin{bmatrix}
    \tfrac52 & \tfrac52
\end{bmatrix}
=
\begin{bmatrix}
    -\tfrac12 & -\tfrac52
\end{bmatrix}.
\]
\end{steppanel}
Since both reduced costs are negative, this confirms that $(0,8)$ is an optimal solution.

target_text:
\[
\c_N^\top -\c_B^\top A_B^{-1} A_N =
\begin{bmatrix}
    2 & 0
\end{bmatrix}
-
\begin{bmatrix}
    5 & 0
\end{bmatrix}
\begin{bmatrix}
    \tfrac12 & \tfrac12 \\
    \tfrac72 & -\tfrac32
\end{bmatrix}
=
\begin{bmatrix}
    2 & 0
\end{bmatrix}
-
\begin{bmatrix}
    \tfrac52 & \tfrac52
\end{bmatrix}
=
\begin{bmatrix}
    -\tfrac12 & -\tfrac52
\end{bmatrix}.
\]
\end{steppanel}
Karena kedua biaya tereduksi bernilai negatif, hal ini menegaskan bahwa $(0,8)$ merupakan solusi optimal.

source_text:
\textbf{Conclusion}
\begin{itemize}
\item \( (6,5) \) is \emph{not necessarily optimal} because it has a positive reduced cost.
\item \( (0,8) \) is \emph{optimal} because all reduced costs are nonpositive.
\end{itemize}
\end{solution}

target_text:
\textbf{Kesimpulan}
\begin{itemize}
\item \( (6,5) \) \emph{tidak optimal} karena memiliki biaya tereduksi yang positif.
\item \( (0,8) \) \emph{optimal} karena semua biaya tereduksinya bernilai nonpositif.
\end{itemize}
\end{solution}

