source_text:
\begin{ex}{Basis matrix and basic solution}{}
\label{ex:matrix-basis-warmup}
\stars{1} Consider the system from Example 1,
\[
\begin{aligned}
    x_1 + 2x_2 + x_3 &= 4, \\
    3x_1 + x_2 + 2x_3 &= 5,
\end{aligned}
\]
and take the basis \( B = \{x_2, x_3\} \).
\begin{enumerate}
    \item Write down the basis matrix \( A_B \) and compute \( A_B^{-1} \).
    \item Compute the basic solution \( \x_B = A_B^{-1}\b \) with \( x_1 = 0 \).
    \item Is this basic solution a basic feasible solution?
\end{enumerate}
\exrefs{\S\ref{sec:solutions-axb}, Example 1}
\end{ex}

target_text:
\begin{ex}{Matriks basis dan solusi basis}{}
\label{ex:matrix-basis-warmup}
\stars{1} Tinjau sistem dari Contoh 1,
\[
\begin{aligned}
    x_1 + 2x_2 + x_3 &= 4, \\
    3x_1 + x_2 + 2x_3 &= 5,
\end{aligned}
\]
dan gunakan basis \( B = \{x_2, x_3\} \).
\begin{enumerate}
    \item Tuliskan matriks basis \( A_B \) dan hitung \( A_B^{-1} \).
    \item Hitung solusi basis \( \x_B = A_B^{-1}\b \) dengan \( x_1 = 0 \).
    \item Apakah solusi basis ini merupakan solusi basis layak?
\end{enumerate}
\exrefs{\S\ref{sec:solutions-axb}, Contoh 1}
\end{ex}

source_text:
\begin{ex}{A basic solution that is not feasible}{}
\label{ex:matrix-infeasible-basis}
\stars{1} For the same system as Exercise~\ref{ex:matrix-basis-warmup}, take the basis \( B = \{x_1, x_3\} \).  Compute \( A_B \), \( A_B^{-1} \), and the basic solution, and explain why this basis gives a basic solution that is \emph{not} feasible.
\exrefs{\S\ref{sec:solutions-axb}, Example 1}
\end{ex}

target_text:
\begin{ex}{Solusi basis yang tidak layak}{}
\label{ex:matrix-infeasible-basis}
\stars{1} Untuk sistem yang sama seperti pada Latihan~\ref{ex:matrix-basis-warmup}, gunakan basis \( B = \{x_1, x_3\} \).  Hitung \( A_B \), \( A_B^{-1} \), dan solusi basisnya, lalu jelaskan mengapa basis ini memberikan solusi basis yang \emph{tidak} layak.
\exrefs{\S\ref{sec:solutions-axb}, Contoh 1}
\end{ex}

source_text:
\begin{ex}{A fourth basis for the three-bases example}{}
\label{ex:matrix-fourth-basis}
\stars{1} In Section~\ref{sec:three-bases} we evaluated the bases \( \{x_1, x_2\} \), \( \{x_1, s_2\} \), and \( \{s_1, s_2\} \) of the system
\[
\begin{bmatrix}
    1 & 2 & 1 & 0 \\
    5 & 3 & 0 & 1
\end{bmatrix}
\begin{bmatrix}
    x_1 \\ x_2 \\ s_1 \\ s_2
\end{bmatrix}
=
\begin{bmatrix}
    16 \\ 45
\end{bmatrix}.
\]
Now evaluate the basis \( B = \{x_2, s_2\} \): compute \( A_B \), \( A_B^{-1} \), and the basic solution, and decide whether it is feasible.  Which point \( (x_1, x_2) \) does this basis correspond to?
\exrefs{\S\ref{sec:three-bases}}
\end{ex}

target_text:
\begin{ex}{Basis keempat untuk contoh tiga basis}{}
\label{ex:matrix-fourth-basis}
\stars{1} Dalam Bagian~\ref{sec:three-bases}, kita telah mengevaluasi basis \( \{x_1, x_2\} \), \( \{x_1, s_2\} \), dan \( \{s_1, s_2\} \) dari sistem
\[
\begin{bmatrix}
    1 & 2 & 1 & 0 \\
    5 & 3 & 0 & 1
\end{bmatrix}
\begin{bmatrix}
    x_1 \\ x_2 \\ s_1 \\ s_2
\end{bmatrix}
=
\begin{bmatrix}
    16 \\ 45
\end{bmatrix}.
\]
Sekarang evaluasi basis \( B = \{x_2, s_2\} \): hitung \( A_B \), \( A_B^{-1} \), dan solusi basisnya, lalu tentukan apakah solusi tersebut layak.  Basis ini bersesuaian dengan titik \( (x_1, x_2) \) yang mana?
\exrefs{\S\ref{sec:three-bases}}
\end{ex}

source_text:
\begin{ex}{Which bases are feasible?}{}
\label{ex:matrix-feasible-bases}
\stars{2} For the \( 2 \times 4 \) system
\[
\begin{bmatrix}
    1 & 2 & 1 & 0 \\
    5 & 3 & 0 & 1
\end{bmatrix}
\begin{bmatrix}
    x_1 \\ x_2 \\ s_1 \\ s_2
\end{bmatrix}
=
\begin{bmatrix}
    16 \\ 45
\end{bmatrix},
\qquad x_1, x_2, s_1, s_2 \geq 0,
\]
there are \( \binom{4}{2} = 6 \) ways to choose two columns.
\begin{enumerate}
    \item Verify that every one of the six column pairs is linearly independent, so each choice is a basis.
    \item For each basis, compute the basic solution and classify it as feasible or infeasible.
    \item Give an example of a \( 2 \times 4 \) matrix in which some pair of columns does \emph{not} form a basis.
\end{enumerate}
\exrefs{\S\ref{sec:three-bases}, Figure~\ref{fig:matrix-bases-geometry}}
\end{ex}

target_text:
\begin{ex}{Basis mana yang layak?}{}
\label{ex:matrix-feasible-bases}
\stars{2} Untuk sistem \( 2 \times 4 \)
\[
\begin{bmatrix}
    1 & 2 & 1 & 0 \\
    5 & 3 & 0 & 1
\end{bmatrix}
\begin{bmatrix}
    x_1 \\ x_2 \\ s_1 \\ s_2
\end{bmatrix}
=
\begin{bmatrix}
    16 \\ 45
\end{bmatrix},
\qquad x_1, x_2, s_1, s_2 \geq 0,
\]
terdapat \( \binom{4}{2} = 6 \) cara untuk memilih dua kolom.
\begin{enumerate}
    \item Verifikasi bahwa setiap pasangan dari keenam pasangan kolom saling bebas linear, sehingga setiap pilihan merupakan basis.
    \item Untuk setiap basis, hitung solusi basis dan klasifikasikan sebagai layak atau tidak layak.
    \item Berikan contoh matriks \( 2 \times 4 \) yang memiliki pasangan kolom yang \emph{tidak} membentuk basis.
\end{enumerate}
\exrefs{\S\ref{sec:three-bases}, Gambar~\ref{fig:matrix-bases-geometry}}
\end{ex}

source_text:
\begin{ex}{Rebuilding a dictionary from the formula}{}
\label{ex:matrix-dictionary-formula}
\stars{2} Section~\ref{sec:optimality-conditions} displays the linear program
\[
\begin{aligned}
\max\quad & 2x + y \\
\st\quad & 3x + y + s_1 = 23,\\
& 5x + 3y + s_2 = 45,\\
& x, y, s_1, s_2 \ge 0,
\end{aligned}
\]
together with its dictionary at the basis \( B = \{x, y\} \).  Using the revised simplex dictionary formula~\eqref{eq:dictionary-general}, compute \( A_B^{-1} \), \( A_B^{-1}\b \), \( A_B^{-1}A_N \), and the reduced costs, and confirm that the formula reproduces the displayed dictionary
\[
\begin{aligned}
\max\quad & 17 - 0.25s_1 - 0.25s_2 \\
\st\quad & x = 6 - 0.75s_1 + 0.25s_2,\\
& y = 5 + 1.25s_1 - 0.75s_2.
\end{aligned}
\]
\exrefs{\S\ref{sec:optimality-conditions}}
\end{ex}

target_text:
\begin{ex}{Membangun kembali kamus dari rumus}{}
\label{ex:matrix-dictionary-formula}
\stars{2} Bagian~\ref{sec:optimality-conditions} menampilkan program linear
\[
\begin{aligned}
\max\quad & 2x + y \\
\st\quad & 3x + y + s_1 = 23,\\
& 5x + 3y + s_2 = 45,\\
& x, y, s_1, s_2 \ge 0,
\end{aligned}
\]
beserta kamusnya pada basis \( B = \{x, y\} \).  Dengan menggunakan rumus kamus simpleks terevisi~\eqref{eq:dictionary-general}, hitung \( A_B^{-1} \), \( A_B^{-1}\b \), \( A_B^{-1}A_N \), dan biaya tereduksi, lalu pastikan bahwa rumus tersebut menghasilkan kembali kamus yang ditampilkan
\[
\begin{aligned}
\max\quad & 17 - 0.25s_1 - 0.25s_2 \\
\st\quad & x = 6 - 0.75s_1 + 0.25s_2,\\
& y = 5 + 1.25s_1 - 0.75s_2.
\end{aligned}
\]
\exrefs{\S\ref{sec:optimality-conditions}}
\end{ex}

source_text:
\begin{ex}{Reduced costs of basic variables}{}
\label{ex:matrix-basic-reduced-zero}
\stars{2} The reduced-cost vector of the nonbasic variables is \( \c_N^\top - \c_B^\top A_B^{-1} A_N \).  Apply the same formula to the \emph{basic} columns: show that
\[
\c_B^\top - \c_B^\top A_B^{-1} A_B = \0^\top,
\]
so every basic variable has reduced cost exactly zero.  Explain what this says about the dictionary at basis \( B \): why can a basic variable never appear in the objective row?
\exrefs{\S\ref{sec:optimality-conditions}}
\end{ex}

target_text:
\begin{ex}{Biaya tereduksi variabel basis}{}
\label{ex:matrix-basic-reduced-zero}
\stars{2} Vektor biaya tereduksi variabel nonbasis adalah \( \c_N^\top - \c_B^\top A_B^{-1} A_N \).  Terapkan rumus yang sama pada kolom \emph{basis}: tunjukkan bahwa
\[
\c_B^\top - \c_B^\top A_B^{-1} A_B = \0^\top,
\]
sehingga setiap variabel basis memiliki biaya tereduksi tepat nol.  Jelaskan implikasinya terhadap kamus pada basis \( B \): mengapa variabel basis tidak pernah dapat muncul pada baris objektif?
\exrefs{\S\ref{sec:optimality-conditions}}
\end{ex}

source_text:
\begin{ex}{Reduced-cost signs and the entering rule}{}
\label{ex:matrix-sign-conventions}
\stars{2} In the dictionary form of Chapter~\ref{ch:simplex-dictionary}, the entering variable is a nonbasic variable with a \emph{positive} coefficient in the objective row, while the optimality theorem of this chapter stops when all reduced costs are \( \leq 0 \).
\begin{enumerate}
    \item Explain why these are the same rule: show that the objective-row coefficient of a nonbasic variable in a dictionary \emph{is} its reduced cost \( c_j - \c_B^\top A_B^{-1} A_{\{j\}} \).
    \item A positive reduced cost signals an improving direction.  Describe geometrically what happens to the solution when that variable increases from zero.
    \item The tableau form of Chapter~\ref{ch:simplex-tableau} instead looks for \emph{negative} \( z \)-row entries.  Using the sign-convention paragraph of \S\ref{par:matrix-sign-conventions}, explain why no contradiction arises.
\end{enumerate}
\exrefs{\S\ref{par:matrix-sign-conventions}, sign-convention paragraph; \S\ref{sec:optimality-conditions}}
\end{ex}

target_text:
\begin{ex}{Tanda biaya tereduksi dan aturan variabel masuk}{}
\label{ex:matrix-sign-conventions}
\stars{2} Dalam bentuk kamus pada Bab~\ref{ch:simplex-dictionary}, variabel masuk adalah variabel nonbasis yang memiliki koefisien \emph{positif} pada baris objektif, sedangkan teorema optimalitas dalam bab ini berhenti ketika semua biaya tereduksi bernilai \( \leq 0 \).
\begin{enumerate}
    \item Jelaskan mengapa keduanya merupakan aturan yang sama: tunjukkan bahwa koefisien variabel nonbasis pada baris objektif suatu kamus \emph{adalah} biaya tereduksinya \( c_j - \c_B^\top A_B^{-1} A_{\{j\}} \).
    \item Biaya tereduksi yang positif menandakan arah perbaikan.  Jelaskan secara geometris apa yang terjadi pada solusi ketika variabel tersebut dinaikkan dari nol.
    \item Sebaliknya, bentuk tableau pada Bab~\ref{ch:simplex-tableau} mencari entri baris \( z \) yang \emph{negatif}.  Dengan menggunakan paragraf konvensi tanda pada \S\ref{par:matrix-sign-conventions}, jelaskan mengapa tidak ada pertentangan.
\end{enumerate}
\exrefs{\S\ref{par:matrix-sign-conventions}, paragraf konvensi tanda; \S\ref{sec:optimality-conditions}}
\end{ex}

source_text:
\begin{ex}{Strictly negative reduced costs imply a unique optimum}{}
\label{ex:matrix-unique-optimum}
\stars{3} Let \( B \) be a basis of an LP in standard form whose basic solution \( \bar\x = (A_B^{-1}\b, \0) \) is feasible, and suppose every reduced cost is \emph{strictly} negative:
\[
\c_N^\top - \c_B^\top A_B^{-1} A_N < \0^\top \quad \text{(componentwise)}.
\]
Prove that \( \bar\x \) is the \emph{unique} optimal solution of the LP.  (This is an argument, not a computation.  Suggested route: take any feasible \( \x \neq \bar\x \), write \( \c^\top \x = \c^\top \bar\x + (\c_N^\top - \c_B^\top A_B^{-1} A_N)\x_N \), and consider the two cases \( \x_N = \0 \) and \( \x_N \neq \0 \).)
\exrefs{\S\ref{sec:optimality-conditions}, Optimality Condition theorem}
\end{ex}

target_text:
\begin{ex}{Biaya tereduksi yang negatif secara ketat menyiratkan optimum unik}{}
\label{ex:matrix-unique-optimum}
\stars{3} Misalkan \( B \) adalah basis suatu PL dalam bentuk standar dengan solusi basis layak \( \bar\x = (A_B^{-1}\b, \0) \), dan andaikan setiap biaya tereduksi bernilai negatif \emph{secara ketat}:
\[
\c_N^\top - \c_B^\top A_B^{-1} A_N < \0^\top \quad \text{(komponen demi komponen)}.
\]
Buktikan bahwa \( \bar\x \) merupakan solusi optimal \emph{unik} dari PL tersebut.  (Ini merupakan suatu argumen, bukan perhitungan.  Rute yang disarankan: ambil sembarang \( \x \neq \bar\x \) yang layak, tulis \( \c^\top \x = \c^\top \bar\x + (\c_N^\top - \c_B^\top A_B^{-1} A_N)\x_N \), lalu tinjau dua kasus \( \x_N = \0 \) dan \( \x_N \neq \0 \).)
\exrefs{\S\ref{sec:optimality-conditions}, teorema Syarat Optimalitas}
\end{ex}

source_text:
\begin{solution}(Exercise~\ref{ex:matrix-basis-warmup})
The columns of \( x_2 \) and \( x_3 \) give
\[
A_B =
\begin{bmatrix}
    2 & 1 \\
    1 & 2
\end{bmatrix},
\qquad
A_B^{-1} = \frac{1}{3}
\begin{bmatrix}
    2 & -1 \\
    -1 & 2
\end{bmatrix}.
\]
The basic solution is
\[
\x_B = A_B^{-1}\b = \frac{1}{3}
\begin{bmatrix}
    2 & -1 \\
    -1 & 2
\end{bmatrix}
\begin{bmatrix}
    4 \\ 5
\end{bmatrix}
= \frac{1}{3}
\begin{bmatrix}
    3 \\ 6
\end{bmatrix}
=
\begin{bmatrix}
    1 \\ 2
\end{bmatrix},
\]
so \( (x_1, x_2, x_3) = (0, 1, 2) \).  Both basic variables are nonnegative, so this is a basic feasible solution.
\end{solution}

target_text:
\begin{solution}(Latihan~\ref{ex:matrix-basis-warmup})
Kolom \( x_2 \) dan \( x_3 \) memberikan
\[
A_B =
\begin{bmatrix}
    2 & 1 \\
    1 & 2
\end{bmatrix},
\qquad
A_B^{-1} = \frac{1}{3}
\begin{bmatrix}
    2 & -1 \\
    -1 & 2
\end{bmatrix}.
\]
Solusi basisnya adalah
\[
\x_B = A_B^{-1}\b = \frac{1}{3}
\begin{bmatrix}
    2 & -1 \\
    -1 & 2
\end{bmatrix}
\begin{bmatrix}
    4 \\ 5
\end{bmatrix}
= \frac{1}{3}
\begin{bmatrix}
    3 \\ 6
\end{bmatrix}
=
\begin{bmatrix}
    1 \\ 2
\end{bmatrix},
\]
sehingga \( (x_1, x_2, x_3) = (0, 1, 2) \).  Kedua variabel basis bernilai nonnegatif, sehingga solusi ini merupakan solusi basis layak.
\end{solution}

source_text:
(Book Selected Solution, verified, with the starting tableau displayed.)
Adding slacks $s_1, s_2$, the initial tableau is
\begin{center}
\renewcommand{\arraystretch}{1.3}
\begin{tabular}{c|cccc|c|c}
Basis & $x$ & $y$ & $s_1$ & $s_2$ & RHS & ratio\\
\hline
$z$   & $-1$ & $\mathbf{-2}$ & $0$ & $0$ & $0$ & \\
\hline
$s_1$ & $1$ & $1$ & $1$ & $0$ & $4$ & $4/1 = 4$\\
$s_2$ & $1$ & $\fbox{3}$ & $0$ & $1$ & $6$ & $6/3 = 2$ (min)\\
\end{tabular}
\end{center}

target_text:
(Solusi pilihan dalam buku, telah diverifikasi, dengan tableau awal
ditampilkan.) Setelah menambahkan variabel slack $s_1, s_2$, tableau awalnya
adalah
\begin{center}
\renewcommand{\arraystretch}{1.3}
\begin{tabular}{c|cccc|c|c}
Basis & $x$ & $y$ & $s_1$ & $s_2$ & RHS & Rasio\\
\hline
$z$   & $-1$ & $\mathbf{-2}$ & $0$ & $0$ & $0$ & \\
\hline
$s_1$ & $1$ & $1$ & $1$ & $0$ & $4$ & $4/1 = 4$\\
$s_2$ & $1$ & $\fbox{3}$ & $0$ & $1$ & $6$ & $6/3 = 2$ (min)\\
\end{tabular}
\end{center}

source_text:
\textbf{Pivot 1:} $y$ enters ($-2$ most negative); ratios $4$ and $2$,
so $s_2$ leaves; pivot on the boxed $3$. Dividing the pivot row by $3$
and clearing the $y$ column gives
\begin{center}
\renewcommand{\arraystretch}{1.3}
\begin{tabular}{c|cccc|c|c}
Basis & $x$ & $y$ & $s_1$ & $s_2$ & RHS & ratio\\
\hline
$z$   & $\mathbf{-\tfrac13}$ & $0$ & $0$ & $\tfrac23$ & $4$ & \\
\hline
$s_1$ & $\fbox{$\tfrac23$}$ & $0$ & $1$ & $-\tfrac13$ & $2$ & $2/\tfrac23 = 3$ (min)\\
$y$   & $\tfrac13$ & $1$ & $0$ & $\tfrac13$  & $2$ & $2/\tfrac13 = 6$\\
\end{tabular}
\end{center}

target_text:
\textbf{Pivot 1:} $y$ masuk ($-2$ adalah yang paling negatif); rasionya $4$
dan $2$, sehingga $s_2$ keluar; lakukan pivot pada $3$ yang diberi kotak.
Membagi baris pivot dengan $3$ dan menolkan kolom $y$ memberikan
\begin{center}
\renewcommand{\arraystretch}{1.3}
\begin{tabular}{c|cccc|c|c}
Basis & $x$ & $y$ & $s_1$ & $s_2$ & RHS & Rasio\\
\hline
$z$   & $\mathbf{-\tfrac13}$ & $0$ & $0$ & $\tfrac23$ & $4$ & \\
\hline
$s_1$ & $\fbox{$\tfrac23$}$ & $0$ & $1$ & $-\tfrac13$ & $2$ & $2/\tfrac23 = 3$ (min) \\
$y$   & $\tfrac13$ & $1$ & $0$ & $\tfrac13$  & $2$ & $2/\tfrac13 = 6$\\
\end{tabular}
\end{center}

source_text:
\textbf{Pivot 2:} $x$ enters ($-\tfrac13$); ratios $3$ and $6$, so $s_1$
leaves; pivot on the boxed $\tfrac23$:
\begin{center}
\renewcommand{\arraystretch}{1.3}
\begin{tabular}{c|cccc|c}
Basis & $x$ & $y$ & $s_1$ & $s_2$ & RHS\\
\hline
$z$   & $0$ & $0$ & $\tfrac12$ & $\tfrac12$ & $5$\\
\hline
$x$ & $1$ & $0$ & $\tfrac32$  & $-\tfrac12$ & $3$\\
$y$ & $0$ & $1$ & $-\tfrac12$ & $\tfrac12$  & $1$\\
\end{tabular}
\end{center}
Every $z$-row entry is nonnegative, so the tableau is optimal:
$(x, y) = (3, 1)$ with $z^* = 5$ (both constraints tight).

