& x_1 + x_2 \leq 10 \\
& 2x_1 - x_2 \leq 5 \\
& -x_1 + 3x_2 \leq 7 \\
& x_1 \text{ bebas, } x_2 \text{ bebas}
\end{aligned}
\]
\end{tcolorbox}

