\begin{aligned}
\text{Maksimumkan} \quad & 4x_1 + 5x_2 + 3x_3 \\
\text{dengan kendala} \quad
& x_1 + 2x_2 + x_3 \leq 10 \\
& 3x_1 + x_2 + 2x_3 \leq 12 \\
& x_1, x_2, x_3 \geq 0
\end{aligned}
\]
\exrefs{\S\ref{sec:duality-theory}, \S\ref{sec:duality-strong}}
