\begin{algorithm}{}{}[Algoritme Tetangga Terdekat Berulang (RNNA)]
\hspace{3in}
\begin{enumerate}
\item	Jalankan Algoritme Tetangga Terdekat dengan memulai dari setiap simpul
\item	Pilih sirkuit yang dihasilkan dengan bobot total minimum
\end{enumerate}
\end{algorithm}

